window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-11-12"]={"date": "2026-11-12", "dateKR": "2026년 11월 12일", "dateEN": "12 November 2026", "total": 60, "sections": [{"code": "TOP", "items": [{"code": "TOP", "date": "2026-11-11", "src": "SAFETY4SEA", "title": "페르시아만·호르무즈 선박 공격 나흘째 이어져 선원 4명 부상 — 11/7 Tarif 피격, 11/10 VLCC Fujairah Energy·ADNOC L&S 선박 손상, JMIC 위협수준 'SEVERE' 유지", "eTitle": "Four Seafarers Injured as Attacks Continue in the Persian Gulf - Tarif Hit on 7 Nov, VLCC Fujairah Energy and an ADNOC L&S Vessel Damaged on 10 Nov, JMIC Keeps the Hormuz Threat Level at SEVERE", "kSum": "11월 5일 카타르 앞바다에서 사망자가 난 유조선 Velos Sapphire 피격 이후 11월 7~10일에도 공격이 이어졌다. 7일 라이베리아기 원유선 Tarif가 호르무즈 통과 중 발사체에 맞았으나 선원은 무사했고 운항도 가능했다. 10일에는 알루와이스에서 두바이로 가던 라이베리아기 VLCC Fujairah Energy가 피격돼 선원 4명이 다쳤고(인도 선원 1명 경상), ADNOC Logistics & Services 운항선도 UAE 영해에서 손상됐다. JMIC는 해협 통항량이 예년 수준을 크게 밑돈다고 평가하며 위협수준을 'SEVERE'로 유지했고, 필리핀 DMW는 자국 선원이 고위험 해역 배치를 거부할 수 있다는 권고를 냈다.", "eSum": "After the fatal attack on the tanker Velos Sapphire off Qatar on 5 November, attacks continued on 7-10 November. On 7 November the Liberian-flagged crude tanker Tarif was hit by a projectile while crossing Hormuz, with the crew safe and the ship operational. On 10 November the Liberian-flagged VLCC Fujairah Energy was struck on passage from Al Ruwais to Dubai, injuring four crew (one Indian seafarer with minor injuries), and an ADNOC Logistics & Services vessel was damaged in UAE territorial waters. JMIC assesses Strait traffic as far below historical levels and keeps the threat level at SEVERE; the Philippine DMW advises that Filipino seafarers may decline deployment to high-risk areas.", "kImp": "걸프·오만만 기항선을 관리하는 회사는 항차별 위협평가와 SSP 보안등급을 다시 확인하고, 필리핀 선원의 고위험 해역 승선 거부권을 감안해 교대·승선 동의 절차를 미리 준비해야 한다. JMIC·UKMTO 경보를 선교 일일 브리핑과 항해계획에 반영하고, 전쟁위험 보험 통지 의무도 점검할 것.", "eImp": "Managers with ships calling the Gulf and Gulf of Oman should re-check voyage threat assessments and SSP security levels, prepare crew-change and consent procedures around the Filipino seafarers' right to decline, feed JMIC/UKMTO warnings into daily bridge briefings and passage plans, and check war-risk notification duties.", "url": "https://safety4sea.com/four-seafarers-injured-as-attacks-on-vessels-continue-in-the-persian-gulf/"}, {"code": "TOP", "date": "2026-11-10", "src": "gCaptain · SAFETY4SEA · 쉬핑뉴스넷", "title": "[후속] 미 USTR, 중국 선박 입항료 유예 연장을 연방관보로 공식화 — 2027년 1월 9일까지, 의견 약 60건 '영구 중단' vs '조선업 위해 유지' 갈려; WSC 등 250여 단체는 영구 중단 요구", "eTitle": "[Follow-up] USTR Formalises the Extension of the China Ship Port Fee Suspension to 9 January 2027 - About 60 Comments Split Between a Permanent End and Keeping the Fees for US Shipbuilding; the WSC and 250 Groups Ask for a Permanent End", "kSum": "USTR이 11월 10일 연방관보 공고로 무역법 301조에 따른 중국 건조·운항 선박 입항료 유예를 2027년 1월 9일 23:59(미 동부)까지 연장했고, 중국도 미국 관련 선박 특별 입항료와 해운·조선 공급망 안보 조사를 1월 10일까지 중단한다. 중국산 STS 크레인 등 하역장비 추가관세 유예도 유지된다. 연장안에는 약 60건의 의견이 들어왔다. 찬성 측은 운임 상승과 상업적 혼란을 피하고 협상 시간을 벌 수 있다며 일부 수수료(Annex III)의 영구 중단을 요구했고, 반대 측은 수수료가 미국 조선·컨테이너 제조업 육성에 필요하다고 주장했다. WSC를 포함한 250여 단체는 10월 30일 영구 중단을 요구하는 공동 서한을 냈으며 RoRo 조항이 우방국 선사에도 영향을 준다고 지적했다. USTR은 1월 시한 전에 재검토할 권한을 유지하고 있다.", "eSum": "USTR's Federal Register notice of 10 November extends the suspension of Section 301 port fees on Chinese-built and Chinese-operated ships to 23:59 ET on 9 January 2027; China keeps its special port fees on US-linked ships and its shipping and shipbuilding supply-chain security probe paused to 10 January. Extra duties on Chinese ship-to-shore cranes and other cargo-handling gear also stay suspended. About 60 comments were filed: supporters said the pause avoids higher freight costs and disruption and buys negotiating time, and some asked for a permanent end to certain fees (Annex III); opponents said the fees are needed to build up US shipbuilding and container manufacturing. More than 250 groups including the World Shipping Council asked on 30 October for a permanent end, noting the ro-ro provisions also hit carriers from allied countries. USTR keeps the right to reconsider before the January deadline.", "kImp": "미국 기항 자동차운반선·중국 건조선을 관리하는 회사는 1월 10일 이후 재부과 가능성을 전제로 선주·용선주와 입항료 부담 주체와 통지 절차를 미리 정리해 둘 것. RoRo 조항의 향방은 12월 중 다시 확인이 필요하다.", "eImp": "Managers of car carriers and Chinese-built ships calling the US should settle with owners and charterers now who bears any fee that may resume from 10 January and how it is notified; re-check the ro-ro provisions in December.", "url": "https://gcaptain.com/u-s-formalizes-two-month-extension-of-china-ship-port-fee-suspension/"}, {"code": "TOP", "date": "2026-11-11", "src": "코리아쉬핑가제트", "title": "HMM·ONE·양밍 프리미어얼라이언스, 부산–지중해 항로 수에즈운하 복귀 — 수에즈 통항 노선 4편으로, ONE SYNERGY 11/29 부산 출항·12/25 운하 통과 예정", "eTitle": "Premier Alliance (HMM, ONE, Yang Ming) Returns Two Asia-Mediterranean Loops to the Suez Canal, Taking Its Suez Services to Four - ONE Synergy Leaves Busan on 29 November and Transits on 25 December", "kSum": "프리미어얼라이언스가 11월부터 아시아–지중해 2개 항로(MP2: 부산–그리스·스페인·이탈리아, MD1: 중국–이집트·튀르키예)의 경유지를 희망봉에서 홍해·수에즈운하로 바꿔 수에즈 통항 노선을 4편으로 늘린다. 1만3000TEU급 ONE SYNERGY호가 11월 29일 부산을 떠나 12월 25일 운하를 통과하고 12월 28일 피레우스에 입항할 예정이며, 양밍 YM TRUST호는 11월 15일 닝보 출항, 12월 6일 첫 통과 예정이다. 얼라이언스는 10월에 INX(IOX) 항로도 수에즈로 전환했다.", "eSum": "From November the Premier Alliance reroutes two Asia-Mediterranean loops (MP2 via Busan to Greece, Spain and Italy; MD1 from China to Egypt and Turkey) from the Cape of Good Hope back to the Red Sea and Suez Canal, taking its Suez services to four. The 13,000 TEU ONE Synergy leaves Busan on 29 November, transits on 25 December and calls Piraeus on 28 December; Yang Ming's YM Trust leaves Ningbo on 15 November for a first transit on 6 December. The alliance already moved its INX (IOX) loop to Suez in October.", "kImp": "주요 컨테이너 얼라이언스의 수에즈 복귀는 홍해 통항 위험 평가가 바뀌고 있다는 신호다. 홍해 통항 지시를 받을 수 있는 선박은 BMP·선사 보안절차, 무장경비·전쟁위험 보험 조건과 선원 동의 절차를 다시 점검해 둘 것.", "eImp": "A major alliance returning to Suez signals a shift in Red Sea risk appetite. Ships that may be ordered through the Red Sea should re-check BMP and company security procedures, armed guard and war-risk terms and crew consent arrangements.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=148420"}]}, {"code": "ACC", "items": [{"code": "ACC", "date": "2026-11-11", "src": "Splash247", "title": "싱가포르서 검사원 선박 이송 중 사망 — 인원 이송 안전규정 강화 요구", "eTitle": "Fatal Surveyor Transfer in Singapore Prompts Calls for Tighter Safety Rules", "kSum": "싱가포르에서 검사원(surveyor)이 선박으로 이송되던 중 숨지는 사고가 발생해, 업계에서 인원 이송 안전규정을 강화해야 한다는 요구가 나왔다. 사고 경위의 세부 내용은 확인된 요약 범위에서 공개되지 않았다.", "eSum": "A surveyor died during a transfer to a ship in Singapore, prompting industry calls for tighter personnel-transfer safety rules. Details of the sequence of events were not given in the summary available.", "kCause": "런치–본선 간 인원 이송(도선사 사다리·현측 사다리) 중 사고", "eCause": "Accident during launch-to-ship personnel transfer (pilot ladder or accommodation ladder)", "kLes": "검사원·감독·기술자 승하선에도 도선사 이송과 같은 기준(SOLAS V/23 사다리 점검, 구명조끼, 조명, 책임사관 입회, 기상 한계)을 적용하고 런치 선택과 이송 중단 권한을 절차에 명시할 것", "eLes": "Apply pilot-transfer standards (SOLAS V/23 ladder checks, lifejacket, lighting, officer attendance, weather limits) to surveyors, superintendents and technicians too, and write launch selection and stop-work authority into the procedure", "url": "https://splash247.com/fatal-surveyor-transfer-prompts-call-for-tighter-safety-rules-in-singapore/"}, {"code": "ACC", "date": "2026-11-10", "src": "gCaptain", "title": "UKMTO 경보 201-26: 오만 리마 북동 19해리에서 유조선이 미확인 발사체에 피격 — 같은 날 ADNOC L&S 선박도 UAE 영해에서 손상", "eTitle": "UKMTO Warning 201-26: Tanker Struck by an Unidentified Projectile 19 nm North-East of Lima, Oman - an ADNOC L&S Vessel Is Damaged in UAE Waters the Same Day", "kSum": "11월 10일 13:38 UTC 호르무즈 인근 오만 리마 북동 약 19해리에서 유조선 1척이 미확인 발사체에 맞았다. 선장은 선원 전원 무사, 환경 피해 없음으로 보고했고 일출 후 손상 평가를 하기로 했다. 같은 날 ADNOC L&S 운항선 1척이 UAE 영해에서 공격으로 손상됐으나 회사는 선명·피해 정도·부상 여부를 밝히지 않았다. 11월 7일 카사브 인근에서는 유조선 화재로 선원이 대피한 바 있다.", "eSum": "At 1338 UTC on 10 November a tanker was struck by an unidentified projectile about 19 nm north-east of Lima, Oman, near the Strait of Hormuz. The master reported all crew safe and no environmental impact, with a damage assessment planned for first light. The same day a vessel operated by ADNOC L&S was damaged in an attack in UAE territorial waters; the company did not disclose the ship, the damage or any injuries. A tanker fire near Khasab on 7 November had already forced a crew to evacuate.", "kCause": "호르무즈 해협·오만 연안 통항 중 발사체 공격 — 발사 주체 미상, JMIC는 추가 고의 공격 가능성을 '매우 높음'으로 평가", "eCause": "Projectile attack on passage near Hormuz and the Omani coast - origin unidentified; JMIC rates further deliberate attacks as highly likely", "kLes": "통항 전 UKMTO 등록·보고, 위험 구간 최소 인원 외 갑판 출입 통제, 손상 시 비상대응(화재·침수·오염)과 일출 후 손상 평가 절차를 승무원과 사전 훈련할 것", "eLes": "Register and report to UKMTO before transit, keep non-essential crew off deck in the risk area, and drill damage response (fire, flooding, pollution) and first-light damage assessment with the crew", "url": "https://gcaptain.com/adnoc-vessel-damaged-in-gulf-attack-as-ukmto-reports-fresh-tanker-strike-near-hormuz/"}, {"code": "ACC", "date": "2026-11-10", "src": "Splash247", "title": "머스크 운항 컨테이너선, 중국 옌톈항에서 안벽 크레인 들이받아 전도", "eTitle": "Maersk-Operated Boxship Knocks Down a Ship-to-Shore Crane at Yantian", "kSum": "머스크가 운항하는 컨테이너선이 중국 옌톈항에서 안벽(STS) 크레인을 들이받아 쓰러뜨렸다. 인명 피해 여부와 구체적 원인은 확인된 요약 범위에서 공개되지 않았다.", "eSum": "A Maersk-operated containership knocked down a ship-to-shore crane at China's Yantian port. Casualties and the specific cause were not given in the summary available.", "kCause": "접·이안 중 선체와 크레인 접촉 — 원인 조사 중(통상 바람·조류, 예인선 협조, 크레인 붐 위치가 쟁점)", "eCause": "Contact between hull and crane during berthing or unberthing - under investigation (wind, current, tug coordination and boom position are the usual issues)", "kLes": "접안 전 도선사·터미널과 크레인 붐 상승·대피 위치를 확인하고, 포트 어세스먼트의 풍속 한계와 예인선 배치를 선교 브리핑에 포함할 것", "eLes": "Confirm with pilot and terminal that crane booms are raised and parked clear before berthing, and brief the port-assessment wind limits and tug plan on the bridge", "url": "https://splash247.com/maersk-boxship-knocks-down-crane-at-yantian/"}]}, {"code": "PCTC", "items": [{"code": "PCTC", "date": "2026-11-11", "src": "쉬핑뉴스넷", "title": "왈레니우스 윌헬름센 3분기 순이익 2억1,200만 달러(전년比 −24%) — 순운임 −2%·물량 −3%, 10월 이후 3년 계약 2건(약 17억 달러) 체결", "eTitle": "Wallenius Wilhelmsen Q3 Net Profit Falls 24% to USD 212m - Net Freight Down 2%, Volumes Down 3% - While Two Three-Year Contracts Worth About USD 1.7bn Are Signed Since October", "kSum": "3분기 매출은 해상운송 부문 증가로 5% 늘어난 14억100만 달러였으나 조정 EBITDA는 10% 줄어든 4억2,800만 달러, 순이익은 24% 감소한 2억1,200만 달러였다. 해상 물량이 전년을 밑돌고 운임이 약세를 보인 영향으로 ㎥당 순운임은 2%, 운송량은 3% 하락했다. 회사는 2026년 연간 조정 EBITDA 전망 16억 달러를 유지했으며, 10월 이후 건설기계·기계 제조사와 아시아 주요 완성차 업체와 각각 3년 계약(합계 약 17억 달러, 한 건은 2년 연장 옵션)을 체결했다.", "eSum": "Q3 revenue rose 5% to USD 1,401m on higher ocean revenue, but adjusted EBITDA fell 10% to USD 428m and net profit fell 24% to USD 212m. Ocean volumes were below last year and rates softer: net freight per cbm was down 2% and volumes down 3%. The company keeps its 2026 adjusted EBITDA outlook at USD 1.6bn and, since October, has signed three-year contracts with a construction and machinery maker and a major Asian carmaker worth about USD 1.7bn in total, one with a two-year extension option.", "kImp": "운임·물량이 동반 약세로 돌아서면 선주는 운항 효율과 off-hire에 더 민감해진다. 자동차선 관리사는 비계획 운항정지 시간과 하역설비(램프·리프터블 데크) 신뢰성을 핵심 지표로 관리해야 한다.", "eImp": "When both rates and volumes soften, owners become more sensitive to efficiency and off-hire. Car carrier managers should treat unplanned unavailability and cargo-gear reliability (ramps, liftable decks) as headline indicators.", "url": "https://www.shippingnewsnet.com/news/articleView.html?idxno=72953"}, {"code": "PCTC", "date": "2026-11-10", "src": "gCaptain", "title": "미 브런즈윅항 자동차 처리능력 확충 — 4번째 RoRo 선석 2027년 12월 개장(10,800 CEU 초과 선박 수용), 10월 한 달 50척 처리", "eTitle": "Port of Brunswick Expands Auto Capacity - a Fourth Ro-Ro Berth Opens in December 2027 for Carriers Above 10,800 CEU, After 50 Vessel Calls in October Alone", "kSum": "조지아항만공사(GPA)가 브런즈윅 Colonel's Island의 RoRo 선석 3개에서 10월 한 달에만 50척을 처리했다. 공정 60%인 4번째 RoRo 선석은 2027년 12월 개장 예정으로 10,800 CEU를 넘는 자동차선을 받을 수 있다. 향후 10년간 약 50억 달러 규모 인프라 계획의 일부이며, 현대차 메타플랜트(2031년까지 8,500명), 리비안(50억 달러), 아우디 첫 미국 공장(40억 달러) 등 조지아 내 완성차 투자가 물량을 끌어올리고 있다.", "eSum": "The Georgia Ports Authority handled 50 vessels in October alone at Brunswick's three ro-ro berths on Colonel's Island. A fourth ro-ro berth, 60% complete, is due to open in December 2027 and will take carriers of more than 10,800 CEU, as part of a nearly USD 5bn infrastructure plan over the next decade. Volumes are driven by carmaker investment in Georgia, including Hyundai's Metaplant (8,500 jobs by 2031), Rivian (USD 5bn) and Audi's first US plant (USD 4bn).", "kImp": "브런즈윅 기항 빈도와 대형선 투입이 늘 전망이다. 기항 선박은 신규 선석의 램프 허용하중·안벽 높이·계류 배치를 포트 어세스먼트에 반영하고, USCG 검사 대비 상태를 유지할 것.", "eImp": "Expect more frequent calls and larger ships at Brunswick. Update port assessments for ramp loads, quay height and mooring layout at the new berth, and stay ready for USCG examinations.", "url": "https://gcaptain.com/port-of-brunswick-expands-auto-shipping-capacity-as-georgia-manufacturing-booms/"}, {"code": "PCTC", "date": "2026-11-10", "src": "Splash247", "title": "MSC 계열 Global Car Carriers, 중국에 자동차선 4척 추가 발주 — 신조 프로그램 26척으로 확대", "eTitle": "MSC-Controlled Global Car Carriers Adds Four Newbuildings in China, Taking Its Programme to 26 Vessels", "kSum": "MSC가 지배하는 Global Car Carriers가 중국 조선소에 자동차운반선 4척을 추가 발주해 신조 프로그램이 26척으로 늘었다. 컨테이너 최대 선사가 자동차선 선복을 빠르게 키우고 있는 흐름이다.", "eSum": "MSC-controlled Global Car Carriers has added four newbuildings in China, expanding its newbuilding programme to 26 vessels - another step in the largest container line's rapid build-up of car carrier tonnage.", "kImp": "신조 대량 인도는 2028년 전후 자동차선 공급 과잉 우려를 키운다. 노후선은 PSC·용선주 검사 성적과 하역설비 상태가 용선 유지의 차별화 요소가 된다.", "eImp": "Heavy deliveries add to oversupply concerns around 2028. For older tonnage, PSC and charterer inspection records and cargo-gear condition become the differentiators for staying on charter.", "url": "https://splash247.com/mscs-car-carrier-arm-adds-four-newbuilds-in-china/"}]}, {"code": "EE", "items": [{"code": "EE", "date": "2026-11-12", "src": "Hellenic Shipping News", "title": "Eni·Fincantieri·RINA, 'Sustainable Maritime Transport Outlook' 2판 발표 — 탈탄소 수단별 감축 잠재력·성숙도·인프라, 2050년까지 총소유비용(TCO) 비교", "eTitle": "Eni, Fincantieri and RINA Present the Second Sustainable Maritime Transport Outlook - Comparing Decarbonisation Options on Abatement, Maturity, Infrastructure and Total Cost of Ownership to 2050", "kSum": "Eni, Fincantieri, RINA가 Bain & Company Italy의 기술 지원을 받아 작성한 보고서 2판을 로마에서 발표했다. 해상운송 탈탄소 수단을 배출 감축 잠재력, 기술 성숙도, 인프라 가용성 기준으로 비교하고 2050년까지의 총소유비용(TCO) 변화를 추적한다.", "eSum": "Eni, Fincantieri and RINA presented in Rome the second edition of the Outlook, developed with technical support from Bain & Company Italy. It compares decarbonisation solutions for shipping on emissions-reduction potential, maturity and infrastructure availability, and tracks total cost of ownership through to 2050.", "kImp": "연료 선택은 TCO와 인프라가 좌우한다는 점을 재확인한다. 선주 대상 연료전환 자문 자료에 이런 비교 프레임을 활용할 수 있다.", "eImp": "It confirms that fuel choice turns on TCO and infrastructure; managers can use the comparison framework in fuel-transition advice to owners.", "url": "https://www.hellenicshippingnews.com/eni-fincantieri-and-rina-present-the-second-edition-of-the-sustainable-maritime-transport-outlook/"}, {"code": "EE", "date": "2026-11-12", "src": "Hellenic Shipping News", "title": "FEET 펀드, '싱가포르-아시아 지속가능금융 택소노미' 2판 첫 채택 — 선박 개조·에너지효율 설비가 적격 대상으로", "eTitle": "FEET Becomes the First Fund to Adopt the Second Edition of the Singapore-Asia Taxonomy for Sustainable Finance, Which Recognises Vessel Retrofits and Energy Efficiency Technology", "kSum": "에너지효율기술펀드(FEET)가 투자 판단 기준으로 싱가포르-아시아 지속가능금융 택소노미 2판을 채택했다. 개정 택소노미는 측정 가능한 배출 감축을 내는 선박 개조와 에너지효율 설비 설치를 적격 활동으로 인정한다. 개정판은 싱가포르통화청(MAS)이 지원하는 싱가포르지속가능금융협회가 COP31에서 발표했다.", "eSum": "The Fund for Energy Efficiency Technologies (FEET) adopted the second edition of the Singapore-Asia Taxonomy for Sustainable Finance to guide investment decisions. The revised taxonomy recognises qualifying vessel retrofits and energy-efficiency technology installations that deliver measurable emissions cuts; it was announced at COP31 by the Singapore Sustainable Finance Association, supported by the MAS.", "kImp": "ESD·풍력보조 등 개조 투자에 녹색금융을 쓰려면 감축 효과를 측정·검증한 데이터가 필요하다. 개조 전후 성능 데이터를 체계적으로 남길 것.", "eImp": "Green finance for retrofits such as ESDs and wind assist needs measured and verified savings, so keep systematic before-and-after performance data.", "url": "https://www.hellenicshippingnews.com/fund-for-energy-efficiency-technologies-feet-is-the-first-fund-to-adopt-the-singapore-asia-taxonomy-for-sustainable-finance/"}, {"code": "EE", "date": "2026-11-12", "src": "Hellenic Shipping News (ENGINE)", "title": "유럽·아프리카 벙커 수급: ARA 즉시 인도분 빠듯 — 5~7일 리드타임 권고, ARA 연료유 재고는 5월 저점比 +57%이나 2월比 −12%", "eTitle": "Europe and Africa Bunker Availability: Prompt Supply Tight in ARA - Allow 5-7 Days' Lead Time; ARA Fuel Oil Stocks Are 57% Above May's Low but 12% Below February", "kSum": "ENGINE에 따르면 ARA 항만의 즉시 인도분 연료 수급이 빠듯해 한 트레이더는 5~7일의 리드타임을 권고했다. Insights Global 자료상 ARA 독립 저장 연료유 재고는 11월 들어 10월 평균보다 2% 높고 5월 저점보다 57% 많지만 2월 수준보다는 12% 낮다.", "eSum": "ENGINE reports tight prompt bunker availability in the ARA ports, with one trader recommending 5-7 days' lead time. Insights Global data show independently held ARA fuel oil stocks averaging 2% above October so far in November, 57% above May's low but still 12% below February levels.", "kImp": "유럽 기항 선박은 벙커 수배를 최소 1주 전에 시작하고, 바지 지연에 대비해 안전 잔량을 넉넉히 둘 것.", "eImp": "Ships calling Europe should start stemming at least a week ahead and keep a comfortable safety margin against barge delays.", "url": "https://www.hellenicshippingnews.com/engine-europe-africa-bunker-fuel-availability-outlook-207/"}, {"code": "EE", "date": "2026-11-11", "src": "Splash247", "title": "COP31서 해운 30여 개 기관 '2035년 국제해운 에너지의 20% 전기화' 목표 제시 — Maritime Electrification 연합", "eTitle": "More Than 30 Maritime Organisations at COP31 Target 20% Electrification of International Shipping's Energy Use by 2035", "kSum": "튀르키예 COP31에서 30개가 넘는 해운 관련 기관이 Maritime Electrification 연합을 통해, 2035년까지 국제해운 에너지 사용의 최소 20%를 전기로 충당하자는 목표를 내놓았다. 육상전원(OPS)과 배터리·하이브리드 추진 확대가 핵심 수단으로 거론된다.", "eSum": "At COP31 in Turkey, more than 30 maritime organisations in the Maritime Electrification coalition called for electricity to supply at least 20% of international shipping's energy use by 2035, with shore power and battery-hybrid propulsion as the main levers.", "kImp": "육상전원 수전 요구가 항만·용선 조건으로 번질 수 있다. 신조·개조 검토 때 OPS 수전 설비와 선내 전력 부하 자료를 준비해 둘 것.", "eImp": "Shore-power demands may spread into port and charter terms. Have OPS connection capability and onboard load data ready for newbuild and retrofit reviews.", "url": "https://splash247.com/maritime-coalition-targets-20-electrification-by-2035/"}, {"code": "EE", "date": "2026-11-11", "src": "The Maritime Executive", "title": "연구: 고래상어 밀집 해역 우회, 6일 이상 항해에서는 연료 증가 1% 이하 — 12일 이상은 0.5% 미만", "eTitle": "Study: Shipping Can Avoid Whale Shark Aggregation Sites at Minimal Cost - at Most 1% More Fuel on Voyages Over Six Days, Under 0.5% Over 12 Days", "kSum": "영국 연구진이 고래상어 밀집 해역을 우회하는 항로를 분석한 결과, 6일을 넘는 항해에서는 우회에 따른 연료 소모 증가가 최대 1%였고 12일을 넘는 항해에서는 0.5% 미만이었다. 더 짧은 횡단에서는 우회보다 밀집 해역 안에서 감속하는 편이 연료 효율이 높았다.", "eSum": "UK researchers modelled rerouting ships around whale shark aggregation sites: on voyages longer than six days it added at most 1% to fuel consumption, and below 0.5% beyond 12 days. For shorter crossings, slowing down inside the aggregation areas was more fuel-efficient than rerouting.", "kImp": "고래류·대형 해양생물 충돌 회피 권고가 늘고 있다. 항해계획에 권고 우회·감속 구역을 반영해도 비용 부담이 작다는 근거로 쓸 수 있다.", "eImp": "Whale and megafauna avoidance advice is growing; this is evidence that building recommended reroutes and slow-down zones into passage plans costs little.", "url": "https://maritime-executive.com/article/study-shipping-can-avoid-endangered-species-habitat-at-minimal-cost"}, {"code": "EE", "date": "2026-11-11", "src": "SMI (MPA)", "title": "싱가포르 MPA–노르웨이 연구위원회, 친환경 해운 공동 연구과제 공모 — 싱가포르 측 최대 270만 싱가포르달러·노르웨이 측 최대 2,000만 크로네, 12/2~1/20 접수", "eTitle": "Singapore's MPA and the Research Council of Norway Launch a Joint Grant Call for Greener Shipping - up to SGD 2.7m and NOK 20m, Applications 2 December to 20 January", "kSum": "싱가포르 해사항만청(MPA)과 노르웨이 연구위원회(RCN)가 11월 11일 친환경 해운 공동 연구과제 공모를 시작했다. 싱가포르해사연구소(SMI)가 싱가포르 측 연구기관에 최대 270만 싱가포르달러, RCN이 노르웨이 측에 최대 2,000만 크로네를 지원한다. 연구 주제는 대체연료와 에너지 인프라, 선박 에너지효율·배출 저감, 디지털화와 친환경 운항이며 접수 기간은 2026년 12월 2일부터 2027년 1월 20일까지다.", "eSum": "Singapore's Maritime and Port Authority and the Research Council of Norway opened a joint research grant call on 11 November. The Singapore Maritime Institute offers up to SGD 2.7m for Singapore research partners and RCN up to NOK 20m for Norwegian partners. Topics are alternative fuels and energy infrastructure, vessel energy efficiency and emissions reduction, and digitalisation for greener operations; applications run from 2 December 2026 to 20 January 2027.", "kImp": "", "eImp": "", "url": "https://www.shipmanagementinternational.com/news/kly5d59ry46dkcg-e2l2l-9nrta-r8bw4-flw4k-hhxde-drbmx-lj7h2-le8dw-c2twb-p79aw-lf3mp-x7lrj-9xgz4-ypwjc-mxead-3sa9y-jyph8-7b93c-jf9r2-36ljk-cz8h5-dfr73-2bb77-j9md4-7fcpt-8ljtk-24lmz-jnm7a"}, {"code": "EE", "date": "2026-11-10", "src": "Splash247", "title": "UCL, IMO 탈탄소 조치의 식량안보 영향 평가 도구 공개", "eTitle": "New UCL Tool Flags Food Security Risks From Shipping Emissions Rules", "kSum": "UCL이 IMO가 논의 중인 해운 탈탄소 조치가 국가별 식량안보에 미칠 영향을 평가하는 도구를 내놓았다. 조치에 따른 운송비 상승이 일부 국가에 불균형하게 작용할 수 있다는 문제의식에서 출발했다. 11월 23~27일 ISWG-GHG와 11월 30일 개막하는 MEPC 85 논의를 앞둔 시점이다.", "eSum": "UCL has released a tool that assesses how the IMO's proposed decarbonisation measures could affect food security by country, on the concern that higher transport costs may fall disproportionately on some states. It lands ahead of ISWG-GHG on 23-27 November and MEPC 85 from 30 November.", "kImp": "", "eImp": "", "url": "https://splash247.com/new-ucl-tool-flags-food-security-risks-from-shipping-emissions-rules/"}, {"code": "EE", "date": "2026-11-09", "src": "SAFETY4SEA (KR)", "title": "한국선급 'FuelEU 저가 준수가 탈탄소 투자를 늦출 수 있다' — 첫 주기 선박의 92%가 풀링, 직접 준수 3%·벌금 3%·차입 2%", "eTitle": "FuelEU Maritime: KR Warns Cheap Compliance May Delay Decarbonisation Investment - 92% of Ships Pooled in the First Cycle, 3% Complied Directly, 3% Paid Penalties and 2% Borrowed", "kSum": "한국선급(KR)은 10월호 탈탄소 매거진 분석에서 FuelEU Maritime 첫 주기에 규제 대상 선박의 92%가 풀링으로 의무를 맞췄고 저탄소 연료·기술로 직접 준수한 선박은 3%, 벌금 납부 3%, 차입 2%였다고 EU 집행위 수치를 인용했다. 초기 감축 목표가 2%로 낮고 잉여분이 과잉 공급되면서 5~7월 잉여분 가격이 크게 떨어졌다. KR 가정에서는 'VLSFO+풀링'이 가장 싸고 B30 바이오연료가 그다음, 'VLSFO+벌금'이 가장 비쌌다. 그러나 목표는 2030년 6%, 2035년 14.5%, 2050년 80%로 강화되고 연속 벌금에는 10% 가산이 붙는다. KR은 잉여분이 부족해지면 풀링 가격이 벌금 수준에 가까워질 수 있다며 선대 단위 준수 계획, 잉여분 적립·판매 결정, 에너지절감장치·풍력보조 추진 검토를 권고했다.", "eSum": "In its October Decarbonization Magazine, Korean Register cites European Commission figures showing that 92% of regulated ships used pooling in the first FuelEU Maritime cycle, 3% complied directly with lower-carbon fuels or technology, 3% paid penalties and 2% borrowed. With a modest 2% initial target and an oversupply of surpluses, surplus prices fell sharply in May-July. Under KR's assumptions VLSFO with pooling was cheapest, B30 biofuel second and VLSFO with penalties the most expensive. But the target rises to 6% in 2030, 14.5% in 2035 and 80% by 2050, and consecutive penalties carry a 10% surcharge. KR expects surpluses to tighten and pooling prices to move toward penalty cost, and recommends fleet-wide compliance planning, a bank-or-sell decision on surpluses, and assessment of energy-saving devices and wind assist.", "kImp": "유럽 기항선은 풀링 비용이 싼 지금 선주와 2030년 이후 준수 경로(연료·ESD·풀 구성)를 합의해 둬야 한다. 정오보고·BDN 데이터 정확도가 풀링 정산의 기초다.", "eImp": "For ships calling Europe, agree the post-2030 compliance path (fuel, ESDs, pool set-up) with owners while pooling is cheap; accurate noon-report and BDN data underpin pool settlement.", "url": "https://safety4sea.com/fueleu-maritime-kr-warns-that-cheap-compliance-may-delay-decarbonization-investment/"}]}, {"code": "DIG", "items": [{"code": "DIG", "date": "2026-11-11", "src": "코리아쉬핑가제트", "title": "부산항만공사, TOC 아시아서 크레인 와이어로프 AI 상시 진단 기술 공개 — 자기센서+융합 AI로 잔존수명 추정, 부산항 5개 터미널 크레인 10대로 확대, 11/13 PSA와 공동 실증 논의", "eTitle": "Busan Port Authority Shows AI-Based Continuous Wire-Rope Diagnosis for Cranes at TOC Asia - Magnetic Sensors Plus a Fused AI Model Estimate Remaining Life; Now on 10 Quay Cranes at Five Busan Terminals, With PSA Talks on 13 November", "kSum": "부산항만공사(BPA)가 11월 10~11일 싱가포르 TOC 아시아 2026에서 엔키아와 공동 개발(2023~2025년 중기부 공동투자 기술개발사업)한 크레인 와이어로프 상시 진단 기술을 공개했다. 로프에 부착한 자기센서가 고밀도 자기장 신호를 하역 중에도 상시 측정해 육안으로 보기 어려운 이상 징후를 잡아내고, 융합형 AI가 하중·속도·운전시간·정비이력을 함께 분석해 위험도와 잔존수명을 추정한다. 신항 3부두 실증에서 이상 징후 식별률 90% 이상을 목표로 검증했고, 2025년 10월부터 확대해 현재 부산항 5개 터미널 안벽크레인 10대에 적용 중이다(해수부 상용화 지원 약 20억 원). 11월 13일 PSA인터내셔널과 공동 실증(PoC)과 기술교류를 논의한다.", "eSum": "At TOC Asia 2026 in Singapore on 10-11 November the Busan Port Authority presented a continuous wire-rope diagnosis technology for cranes, co-developed with Nkia under a 2023-2025 SME ministry joint R&D programme. Magnetic sensors on the rope measure high-density magnetic field signals while the crane keeps working, picking up anomalies that visual checks miss, and a fused AI model combines load, speed, running hours and maintenance history to rate risk and estimate remaining life. Trials at New Port Pier 3 targeted an anomaly detection rate above 90%; since October 2025 it has been extended to 10 quay cranes at five Busan terminals, with about KRW 2bn of MOF commercialisation support. A joint proof of concept with PSA International is to be discussed on 13 November.", "kImp": "와이어로프 상태 기반 진단은 선박의 리프터블 데크·램프·크레인 와이어 관리에도 응용 여지가 있다. 주기 교체에서 상태 기반 교체로 넘어가려면 센서 데이터와 정비이력을 함께 쌓아야 한다.", "eImp": "Condition-based wire-rope diagnosis could also be applied to shipboard liftable deck, ramp and crane wires; moving from time-based to condition-based renewal needs sensor data and maintenance history kept together.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=148486"}, {"code": "DIG", "date": "2026-11-10", "src": "gCaptain", "title": "Hapag-Lloyd와 Inmarsat Maritime: 300척·133개 서비스 선대의 연결성 사례", "eTitle": "Hapag-Lloyd and Inmarsat Maritime: a Case Study in Connected Shipping Across 300 Vessels and 133 Liner Services", "kSum": "세계 5위 컨테이너 선사 Hapag-Lloyd는 133개 정기 서비스에 300척을 운항하며 연 1,350만 TEU를 수송한다. 이 선대의 선박-육상 연결성 구축 사례를 네트워크 운영 책임자(Patrick Briest)의 설명으로 다룬 기사다.", "eSum": "Hapag-Lloyd, the world's fifth-largest container carrier, operates 300 vessels on 133 liner services and carries 13.5m TEU. The piece presents its ship-shore connectivity build-out as a case study, featuring Patrick Briest, Senior Director IT - Network Operations.", "kImp": "대형 선대의 연결성 표준이 높아지면 원격 지원·데이터 보고 요구도 관리선으로 번진다. 선박별 통신 용량과 사이버 보안 통제를 함께 점검할 것.", "eImp": "As large fleets raise the connectivity standard, remote-support and data-reporting demands spread to managed ships - review per-ship bandwidth together with cyber controls.", "url": "https://gcaptain.com/hapag-lloyd-and-inmarsat-maritime-a-case-study-in-connected-shipping/"}]}, {"code": "TECH", "items": [{"code": "TECH", "date": "2026-11-12", "src": "Hellenic Shipping News", "title": "Everllence, 인도 SDHI의 18,000dwt 케미컬탱커 6척에 2행정 이중연료 엔진 공급 — 인도 첫 케미컬탱커 신조", "eTitle": "Everllence Two-Stroke Dual-Fuel Engines Selected for Six 18,000 dwt Chemical Tankers at India's SDHI - India's First Chemical Tanker Order", "kSum": "Swan Defence and Heavy Industries(SDHI)가 Everllence에 2행정 이중연료 엔진을 발주했다. 엔진은 18,000dwt급 IMO Type II 케미컬탱커 6척 시리즈에 탑재되며, SDHI의 첫 2행정 신조 계약이자 인도 최초의 케미컬탱커 수주다.", "eSum": "Swan Defence and Heavy Industries (SDHI) ordered two-stroke dual-fuel engine technology from Everllence for a series of six 18,000 dwt IMO Type II chemical tankers - SDHI's first two-stroke newbuild contract and India's first chemical tanker order.", "kImp": "인도 조선소의 상선 신조 진입이 본격화되고 있다. 신흥 조선소 건조선은 인수 시 건조감리·보증 클레임 체계를 더 촘촘히 가져가야 한다.", "eImp": "Indian yards are moving into merchant newbuilding; ships from emerging yards need tighter site supervision and warranty-claim arrangements at takeover.", "url": "https://www.hellenicshippingnews.com/everllence-two-stroke-dual-fuel-technology-selected-for-landmark-indian-chemical-tanker-project/"}, {"code": "TECH", "date": "2026-11-12", "src": "쉬핑뉴스넷", "title": "COSCO, VLCC 24척 확충 — 자체 발주 10척(2029~2030년 인도)·중국 리스사 장기 나용선 14척(10척은 LNG 이중연료)", "eTitle": "COSCO Shipping Energy to Add 24 VLCCs - 10 Owned Newbuildings for 2029-2030 and 14 on Long-Term Bareboat Charter From Chinese Lessors, 10 of Them LNG Dual-Fuel", "kSum": "COSCO Shipping Energy Transportation이 VLCC 24척을 확충한다. 자체 발주 10척은 양저우 COSCO 중공(6척)과 CSSC 다롄조선(4척)에 척당 약 9억4,800만 위안으로 발주해 2029년 8월~2030년 11월 인도받는다. 나머지 14척은 중국 리스사 6곳에서 최장 20년 나용선으로 2030년에 도입하며, 이 중 10척이 LNG 이중연료선이다.", "eSum": "COSCO Shipping Energy Transportation will add 24 VLCCs: 10 owned newbuildings split between Yangzhou COSCO Shipping Heavy Industry (6) and CSSC's DSIC (4) at about CNY 948m each for delivery from August 2029 to November 2030, and 14 on bareboat charter of up to 20 years from six Chinese leasing firms, all due in 2030, of which ten are LNG dual-fuel.", "kImp": "대형 유조선에서도 LNG 이중연료가 표준 사양이 되고 있다. 가스연료선 승선 경력 사관(IGF) 확보 경쟁이 더 심해질 전망이다.", "eImp": "LNG dual-fuel is becoming a standard spec even for large tankers, so competition for IGF-experienced officers will intensify.", "url": "https://www.shippingnewsnet.com/news/articleView.html?idxno=72974"}, {"code": "TECH", "date": "2026-11-12", "src": "Hellenic Shipping News", "title": "UMOE Advanced Composites, 중국산 Type IV 복합재 가스용기(MEGC) 5기 호주 수소·암모니아 프로젝트로 첫 수출", "eTitle": "UAC Ships Its First Multi-Element Gas Containers From China - Five Units With Type IV Glass-Fibre Cylinders for an Australian Hydrogen and Ammonia Project", "kSum": "UMOE Advanced Composites가 자싱 공장에서 MEGC 5기(20피트 2기, 40피트 3기)를 완성해 호주 뉴사우스웨일스의 Good Earth 그린수소·암모니아 프로젝트로 선적한다. 중국에서 제조된 첫 Type IV 유리섬유 압력용기를 사용했다.", "eSum": "UMOE Advanced Composites completed five multi-element gas containers (two 20-foot, three 40-foot) at its Jiaxing facility for the Good Earth Green Hydrogen and Ammonia Project in New South Wales, using the first Type IV glass-fibre pressure cylinders made in China.", "kImp": "", "eImp": "", "url": "https://www.hellenicshippingnews.com/uac-reaches-global-growth-milestone-with-first-international-megc-shipment-from-china/"}, {"code": "TECH", "date": "2026-11-11", "src": "Splash247", "title": "영국 해군, 수중 감시 프로그램 상업 파트너로 Ocean Infinity 선정 — 초기 9,000만 파운드", "eTitle": "UK Taps Ocean Infinity as the Royal Navy's Commercial Partner for an Underwater Surveillance Programme Backed by an Initial GBP 90m", "kSum": "Ocean Infinity가 초기 9,000만 파운드(약 1억2천만 달러)가 투입되는 영국 해군 수중 감시 프로그램의 상업 임무 파트너로 선정됐다. 해저 케이블·파이프라인 등 핵심 기반시설 보호 수요를 반영한다.", "eSum": "Ocean Infinity has been selected as the Royal Navy's commercial mission partner for an underwater surveillance programme backed by an initial GBP 90m (about USD 120m), reflecting demand to protect subsea cables and pipelines.", "kImp": "", "eImp": "", "url": "https://splash247.com/uk-taps-ocean-infinity-for-subsea-security-push/"}, {"code": "TECH", "date": "2026-11-10", "src": "코리아쉬핑가제트", "title": "CMA CGM·나이키·Gemadept, 베트남서 100% 전기 바지선 운항 개시", "eTitle": "CMA CGM, Nike and Gemadept Launch a Zero-Direct-Emission Electric Barge in Vietnam", "kSum": "CMA CGM, 나이키, 베트남 Gemadept가 베트남에서 완전 전기 추진 바지선 솔루션을 공식 출시했다. 내륙 운송 구간의 탄소발자국을 줄여 나이키 공급망 탈탄소화를 지원하도록 설계됐다.", "eSum": "CMA CGM, Nike and Vietnam's Gemadept officially launched a fully electric barge solution in Vietnam, designed to cut the carbon footprint of inland transport and support the decarbonisation of Nike's supply chain.", "kImp": "", "eImp": "", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=148464"}]}, {"code": "HR", "items": [{"code": "HR", "date": "2026-11-11", "src": "Splash247", "title": "중국, 초급사관 확보 경쟁 심화 — 임금 상승세", "eTitle": "China Faces a Growing Scramble for Junior Officers as Wages Edge Higher", "kSum": "중국 선원 시장에서 초급사관을 확보하려는 경쟁이 커지면서 임금이 오르고 있다는 보도다. 신조 인도 증가와 사관 공급 부족이 겹친 결과로 풀이된다.", "eSum": "Competition for junior officers in China's crewing market is intensifying and wages are edging higher, as newbuilding deliveries meet a shortage of officers.", "kImp": "중국 선원을 쓰는 선대는 초급사관 임금·충원 리드타임 상승을 예산에 반영하고, 사관후보생 양성과 승진 경로로 유지율을 높일 것.", "eImp": "Fleets using Chinese crew should budget for higher junior-officer wages and longer lead times, and lift retention through cadet pipelines and promotion paths.", "url": "https://splash247.com/china-faces-growing-scramble-for-junior-officers-as-wages-edge-higher/"}, {"code": "HR", "date": "2026-11-11", "src": "Splash247", "title": "필리핀, 승선경력 일부를 시뮬레이터 훈련으로 대체하는 방안 검토", "eTitle": "Philippines Explores a Simulator Alternative to Sea Time", "kSum": "필리핀이 해기사 양성 과정에서 요구되는 승선경력의 일부를 시뮬레이터 훈련으로 대체하는 방안을 검토하고 있다. 사관후보생 승선 자리 부족이 배경이다.", "eSum": "The Philippines is considering simulator training as an alternative to part of the sea time required of officer candidates, against a shortage of cadet berths.", "kImp": "제도화되면 사관후보생 승선 계획과 STCW 인정 범위가 달라진다. 필리핀 사관을 쓰는 회사는 진행 상황과 기국·용선주의 수용 여부를 지켜볼 것.", "eImp": "If adopted it would change cadet berth planning and STCW recognition; companies using Filipino officers should track progress and whether flags and charterers accept it.", "url": "https://splash247.com/philippines-explores-simulator-alternative-to-sea-time/"}, {"code": "HR", "date": "2026-11-11", "src": "Splash247", "title": "해운 기술 도입 붐, 선원들은 따라가기 벅차", "eTitle": "Shipping's Technology Boom Leaves Seafarers Struggling to Keep Up", "kSum": "선박에 새 시스템과 디지털 도구가 빠르게 도입되면서 선원들이 이를 따라가는 데 어려움을 겪고 있다는 지적이다. 교육과 친숙화 시간이 도입 속도를 따라가지 못하는 문제가 제기됐다.", "eSum": "Seafarers are finding it hard to keep pace as new systems and digital tools arrive on board faster than training and familiarisation time allows.", "kImp": "새 시스템 도입 시 MOC에 선원 교육·친숙화 시간과 업무량 영향을 반영하고, 현장 피드백으로 절차를 단순화할 것.", "eImp": "Build crew training, familiarisation time and workload impact into the MOC for any new system, and simplify procedures using onboard feedback.", "url": "https://splash247.com/shippings-technology-boom-leaves-seafarers-struggling-to-keep-up/"}]}, {"code": "HSEQ", "items": [{"code": "HSEQ", "date": "2026-11-12", "src": "Hellenic Shipping News", "title": "Nishi-F FF-65 자유낙하식 구명정 안전 통지 — 2010년 10월 이후 제작 25인승, 통로 유효폭이 LSA Code 4.7.2.1의 480mm에 못 미칠 수 있어 점검 필요", "eTitle": "Nishi-F Safety Notice for FF-65 Free-Fall Lifeboats - 25-Person Units Built From October 2010 May Have an Aisle Passage Narrower Than the 480 mm Required by LSA Code 4.7.2.1", "kSum": "Nishi-F가 2010년 10월 이후 제작된 25인승 FF-65 자유낙하식 구명정에 대해 제품 안전 통지를 냈다. 해당 구명정은 좌석 배치에 따라 통로 유효폭이 IMO LSA Code 4.7.2.1항이 요구하는 480mm에 못 미칠 수 있다. 제조사는 시정 조치를 마련하고 해당 구명정 점검 방법을 안내했다.", "eSum": "Nishi-F issued a product safety notice for 25-person FF-65 free-fall lifeboats manufactured from October 2010 onwards: the seating may leave a clear passage width below the 480 mm required by paragraph 4.7.2.1 of the IMO LSA Code. The maker has developed corrective measures and issued instructions for checking the affected boats.", "kImp": "관리선에 Nishi-F FF-65가 탑재돼 있는지 구명설비 목록에서 확인하고, 해당되면 통로 폭을 실측해 제조사·선급에 통보할 것. PSC에서 구명정 결함은 출항정지 사유가 될 수 있다.", "eImp": "Check LSA inventories for Nishi-F FF-65 boats and, where fitted, measure the passage width and notify the maker and class - lifeboat defects can be detainable at PSC.", "url": "https://www.hellenicshippingnews.com/nishi-f-ff-65-free-fall-lifeboats-verification-of-aisle-passage-width/"}, {"code": "HSEQ", "date": "2026-11-12", "src": "쉬핑뉴스넷", "title": "해수부·해운조합, 내항여객선사 경영층 32명 대상 안전교육 — 사고사례·재발방지, 교통약자 서비스", "eTitle": "MOF and the Korea Shipping Association Hold Safety Training for 32 Coastal Passenger Ship Executives - Accident Cases, Recurrence Prevention and Service for Mobility-Impaired Passengers", "kSum": "해양수산부와 한국해운조합이 11월 5일 조합 대회의실에서 '2026년도 내항여객선사 경영층 안전교육'을 열었다. 선사 경영진 32명과 해수부·한국해양교통안전공단(KOMSA)·조합 관계자가 참석해 여객선 사고사례와 재발방지 방안, 교통약자 서비스 교육을 받았고, 해수부 연안해운과장이 내항여객선 정책과 현안을 설명했다.", "eSum": "The Ministry of Oceans and Fisheries and the Korea Shipping Association held the 2026 safety training for coastal passenger ship executives on 5 November, attended by 32 company executives with MOF, KOMSA and association officials. It covered passenger ship accident cases and recurrence prevention and service for mobility-impaired passengers, with the MOF coastal shipping director briefing on policy.", "kImp": "경영층 대상 안전교육은 ISM의 '최고경영자 책임'을 실질화하는 수단이다. 외항 관리사도 경영검토에 사고사례 학습을 정례화할 수 있다.", "eImp": "Executive-level safety training gives substance to top-management commitment under the ISM Code; deep-sea managers can likewise make accident case learning a fixed part of management reviews.", "url": "https://www.shippingnewsnet.com/news/articleView.html?idxno=72969"}, {"code": "HSEQ", "date": "2026-11-09", "src": "SMI (INTERTANKO)", "title": "INTERTANKO: 걸프·호르무즈 공격 '더 흉포해져' — 공격당 2발 이상, 선미 기관실 부근 조준, 항해 중인 선체에 소형정이 림펫형 기뢰 부착한 사례 2건 이상", "eTitle": "INTERTANKO: Attacks in the Gulf and Strait of Hormuz Have Grown in Ferocity - at Least Two Munitions per Attack, Aimed Aft Near the Engine Room, and Limpet-Style Mines Attached by Small Boats to Ships Under Way in at Least Two Cases", "kSum": "INTERTANKO는 11월 6일 주간 권고에서 걸프 주변 지역은 비교적 잠잠해졌지만 걸프 내부와 호르무즈 해협의 공격은 여전히 높은 수준이며 더 격렬해졌다고 평가했다. 공격자는 표적 선박을 멈춰 세워 무력화하려는 의도로 보이며, 한 번의 공격에 최소 2발을 쓰고 기관실이 있는 선미 쪽을 정밀하게 겨냥한다. 최소 2건에서는 소형정이 항해 중인 선박의 선체에 림펫형 기뢰를 부착했다. 미국 선거 결과가 종전 압력으로 작용할 수 있으나 분쟁은 당분간 이어질 것으로 봤다.", "eSum": "In its weekly advice of 6 November INTERTANKO says the wider region is relatively calm but attacks inside the Gulf and the Strait of Hormuz remain at a high level and have grown more violent. Attackers appear to aim to stop and disable ships, using at least two munitions per attack with more precise targeting of the aft end near the engine room; in at least two attacks small boats attached limpet-style mines to hulls while the ships were under way. The US election result may push toward ending the war, but INTERTANKO expects the conflict to continue for some time.", "kImp": "선미·기관실 피격을 전제로 한 비상대응(기관실 화재·침수, 조타 상실, 비상발전)과 소형정 접근 감시(견시 증원, 야간 조명·열상 장비), 통과 후 선체 수선부 점검 절차를 통항 전 훈련에 넣을 것.", "eImp": "Build pre-transit drills around a hit aft - engine-room fire and flooding, loss of steering, emergency power - with small-boat watch (extra lookouts, lighting, thermal imaging) and a waterline hull check after transit.", "url": "https://www.shipmanagementinternational.com/news/kly5d59ry46dkcg-e2l2l-9nrta-r8bw4-flw4k-hhxde-drbmx-lj7h2-le8dw-c2twb-p79aw-lf3mp-x7lrj-9xgz4-ypwjc-mxead-3sa9y-jyph8"}]}, {"code": "KR", "items": [{"code": "KR", "date": "2026-11-12", "src": "쉬핑뉴스넷", "title": "4개 항만공사 노조 '통합 기획 용역 즉각 중단' 공동 성명 — 해수부는 자회사 통합 노사 간담회 개최", "eTitle": "Unions at Korea's Four Port Authorities Demand an Immediate Halt to the Integration Study, as MOF Holds a Labour-Management Meeting on Merging Subsidiaries", "kSum": "부산·인천·울산·여수광양 항만공사 노동조합이 11월 12일 공동 성명을 내고 해양수산부의 항만공사 통합 기획 용역을 즉각 중단하라고 요구했다. 노조는 통합 필요성을 처음부터 다시 검증하고 노조·지역사회·항만 종사자·고객과 실질적으로 소통하라고 촉구했다. 정부의 9월 3일 공공기관 통폐합 발표 뒤 해수부가 통합 로드맵 용역을 긴급 발주한 것이 배경이며, 해수부는 11월 11일 항만공사 자회사 통합을 위한 노사 간담회를 열었다.", "eSum": "The unions of the Busan, Incheon, Ulsan and Yeosu-Gwangyang port authorities issued a joint statement on 12 November demanding that MOF immediately stop its study on integrating the port authorities, re-verify the need from scratch and consult unions, local communities, port workers and customers. The ministry urgently tendered the roadmap study after the government's 3 September announcement on merging public institutions, and held a labour-management meeting on merging port authority subsidiaries on 11 November.", "kImp": "항만공사 체계가 바뀌면 항만시설 사용료·입출항 행정 창구가 달라질 수 있어 국내 기항 선박의 대리점 업무에 영향이 있을 수 있다.", "eImp": "A change in port authority structure could alter port dues and administrative contact points, affecting agency work for ships calling Korean ports.", "url": "https://www.shippingnewsnet.com/news/articleView.html?idxno=72977"}, {"code": "KR", "date": "2026-11-12", "src": "쉬핑뉴스넷", "title": "1~10월 한중 카페리 컨테이너 50만5,188TEU(+6.2%)·여객 80만9,263명(+25.7%) — 평택–일조 5만6,405TEU로 최다, 4개 노선은 신조선 미확보로 중단", "eTitle": "Korea-China Car Ferry Routes Carry 505,188 TEU (+6.2%) and 809,263 Passengers (+25.7%) in January-October - Pyeongtaek-Rizhao Leads With 56,405 TEU; Four Routes Remain Suspended for Lack of New Ferries", "kSum": "올해 1~10월 한중 카페리 항로의 컨테이너 물동량은 50만5,188TEU로 전년 동기보다 6.2%, 여객은 80만9,263명으로 25.7% 늘었다. 노선별로는 평택–일조 5만6,405TEU(+17.4%)가 가장 많았고 인천–석도 5만4,146TEU(+8.4%), 평택–연태 5만2,185TEU(+17.1%), 인천–연운항 5만1,350TEU(+17.2%)가 뒤를 이었다. 인천–청도는 21.9% 줄었다. 인천–천진·영구·대련과 평택–영성 노선은 신조 카페리선을 확보하지 못해 중단 상태다. 10월 항로 평균 소석률은 57.74%, 인바운드 비중은 약 70%, 여객의 90.36%는 중국인이었다.", "eSum": "Korea-China car ferry routes carried 505,188 TEU in January-October, up 6.2% year on year, and 809,263 passengers, up 25.7%. Pyeongtaek-Rizhao led with 56,405 TEU (+17.4%), followed by Incheon-Shidao 54,146 TEU (+8.4%), Pyeongtaek-Yantai 52,185 TEU (+17.1%) and Incheon-Lianyungang 51,350 TEU (+17.2%); Incheon-Qingdao fell 21.9%. The Incheon-Tianjin, -Yingkou and -Dalian and Pyeongtaek-Rongcheng routes remain suspended for lack of new ferries. In October the average load factor was 57.74%, inbound cargo was about 70% and 90.36% of passengers were Chinese.", "kImp": "중단 노선의 원인은 신조 카페리 확보 지연이다. 노후 카페리 대체 수요가 이어져 국내 Ro-Pax 관리·인수 업무 기회가 될 수 있다.", "eImp": "The suspended routes are waiting for new ferries; replacement of ageing tonnage keeps creating Ro-Pax takeover and management work.", "url": "https://www.shippingnewsnet.com/news/articleView.html?idxno=72972"}, {"code": "KR", "date": "2026-11-11", "src": "코리아쉬핑가제트", "title": "한국해양대–한국선급, 조선·해양 기술협력 및 연구성과 제3자 검증 MOU", "eTitle": "Korea Maritime & Ocean University and Korean Register Sign an MOU on Shipbuilding and Offshore Technology Cooperation and Third-Party Verification", "kSum": "한국해양대 앵커사업단이 11월 4일 한국선급(KR) 신성장사업단과 업무협약을 맺었다. 조선·해양 분야 기술협력과 대학 연구성과물의 제3자 검증을 다루며, 연구개발 성과를 고도화해 실용화하려는 취지다.", "eSum": "KMOU's anchor project group signed an MOU with Korean Register's new growth business unit on 4 November covering technology cooperation in shipbuilding and offshore and third-party verification of research output, to advance university R&D toward practical use.", "kImp": "", "eImp": "", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=148478"}, {"code": "KR", "date": "2026-11-11", "src": "쉬핑뉴스넷 (TradeWinds)", "title": "한화쉬핑 첫 LNG선 2척, BP와 3년 용선(2년 연장 옵션 2회)…2027년 6·9월 인도, 일 7만~7만5,000달러 거론", "eTitle": "Hanwha Shipping's First Two LNG Carriers Go to BP for Three Years With Two Two-Year Options - Delivery in June and September 2027 at a Reported USD 70,000-75,000 per Day", "kSum": "메리츠증권이 트레이드윈즈 보도를 인용해 전한 바에 따르면, 한화쉬핑이 한화오션에 발주한 첫 LNG운반선 2척을 BP가 3년간 용선한다. 2년씩 두 차례 연장 옵션이 붙고 용선료는 하루 7만~7만5,000달러 수준으로 거론된다. 선박은 2027년 6월과 9월에 1척씩 인도된다. 한화는 필라델피아 조선소 인력을 국내 건조 현장에 투입해 10년간 기술을 이전하고 2028년부터 미국에서도 LNG선을 건조할 계획으로 알려졌다. 다만 중동 분쟁으로 LNG 공급 확대가 늦어지며 시장 회복은 2028년으로 밀렸고, 2027년 인도 예정인 용선 미확정 LNG선 15척이 운임을 누를 수 있다는 전망이다.", "eSum": "Citing TradeWinds, Meritz Securities reports that BP will charter for three years the first two LNG carriers Hanwha Shipping ordered at Hanwha Ocean, with two two-year extension options and a rate said to be USD 70,000-75,000 per day. The ships deliver in June and September 2027. Hanwha is said to plan a ten-year technology transfer by placing Philly Shipyard staff at its Korean yard, with LNG carrier construction in the US from 2028. The Middle East conflict has delayed LNG supply growth and pushed market recovery to 2028, and 15 uncommitted LNG carriers due in 2027 could weigh on rates.", "kImp": "신규 LNG선 선주의 등장은 가스선 관리 수요와 경력 사관 확보 경쟁을 함께 키운다.", "eImp": "A new LNG carrier owner adds both gas ship management demand and competition for experienced officers.", "url": "https://www.shippingnewsnet.com/news/articleView.html?idxno=72965"}, {"code": "KR", "date": "2026-11-10", "src": "코리아쉬핑가제트", "title": "부산항만공사–삼성SDS, AI·디지털트윈 기반 스마트항만 구축 업무협약", "eTitle": "Busan Port Authority and Samsung SDS Sign an MOU on an AI and Digital-Twin Smart Port", "kSum": "부산항만공사(BPA)가 11월 10일 사옥에서 삼성SDS와 '디지털·AI 항만, 물류 혁신 업무협약'을 체결했다. 협력 분야는 ① 글로벌 물류 분야 디지털 연계 ② 스마트항만 인공지능 전환(AX) ③ 기술·업무 정기 교류 세 가지로, 삼성SDS의 글로벌 물류·AI·디지털트윈·클라우드 역량을 부산항 운영 전문성과 결합해 운영 효율과 안전성을 높이는 것이 목표다. 양측은 협약 전부터 물류 시스템 운영 사례를 공유해 왔으며, 구체적 실행 일정은 공개되지 않았다.", "eSum": "The Busan Port Authority signed an MOU with Samsung SDS at its headquarters on 10 November on digital and AI port and logistics innovation. It covers three areas - digital links in global logistics, AI transformation of the smart port, and regular technical and working-level exchange - combining Samsung SDS's logistics, AI, digital-twin and cloud capability with Busan's operating expertise to raise efficiency and safety. The two had already been sharing logistics system operating cases; no implementation timetable was given.", "kImp": "부산항의 AI 전환이 진행되면 선박 입출항·선석 배정 정보의 디지털 연계 요구가 늘 수 있다. 기항 선박의 ETA·하역 계획 데이터 정확도가 더 중요해진다.", "eImp": "As Busan's AI transformation proceeds, expect more digital exchange of arrival and berth-planning data; accurate ETA and cargo-plan data from calling ships will matter more.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=148473"}, {"code": "KR", "date": "2026-11-10", "src": "gCaptain", "title": "창원시, 진해신항(21선석·2만5,000TEU급)을 북극항로 허브로 — 1단계 9선석 2033년 개장 목표, 내빙선·기자재·정비 공급기지 구상", "eTitle": "Changwon Wants Jinhae New Port (21 Berths for Ships up to 25,000 TEU) to Be an Arctic Shipping Hub - First Nine Berths Targeted for 2033, With a Supply Base for Ice-Class Ships, Equipment and Maintenance", "kSum": "창원시(강기윤 시장)가 진해신항을 '북극항로 시대'의 허브로 키우겠다는 구상을 내놓았다. 진해신항은 2만5,000TEU급 컨테이너선용 21선석과 698만㎡ 배후단지로 계획돼 있고 1단계 9선석은 2033년 개장이 목표다. 창원은 별도의 북극 전용항을 짓기보다 북극항로 물동량을 신항 개발과 창원국가산단 제조 기반에 묶어 내빙선·선박 기자재·정비 서비스를 공급하는 방안을 제시한다. 정부는 2030년까지 북극 컨테이너 정기 서비스를 목표로 하지만 상업성은 검증되지 않았다 — 시험 운항한 PanStar Acro(2,758TEU)는 부산–유럽 50일 왕복에서 수출 적재 737TEU(예상 약 1,300TEU)에 그쳤고 수입 적재 화물은 없었다.", "eSum": "Changwon's mayor Kang Ki-yoon wants Jinhae New Port to take on a role in the 'Arctic shipping era'. The port is planned with 21 berths for container ships up to 25,000 TEU and a 6.98 million sq m logistics hinterland, with the first nine berths targeted for 2033. Rather than a separate Arctic port, the city proposes folding Northern Sea Route traffic into Jinhae and the Changwon National Industrial Complex to supply ice-strengthened ships, marine equipment and maintenance. Seoul aims for regular Arctic container services by 2030, but viability is unproven: the test ship PanStar Acro (2,758 TEU) completed a 50-day Busan-Europe round trip with only 737 TEU of loaded exports against about 1,300 expected, and no loaded imports.", "kImp": "북극항로 운항은 Polar Code 인증, 내빙 등급, 극지 승무원 교육이 전제다. 정책이 구체화되면 극지 운항 경험 사관과 절차 준비가 필요해진다.", "eImp": "Arctic trading requires Polar Code certification, ice class and polar crew training; as policy firms up, polar-experienced officers and procedures will be needed.", "url": "https://gcaptain.com/south-korea-looks-to-position-jinhae-new-port-as-arctic-shipping-hub/"}]}, {"code": "INS", "items": [{"code": "INS", "date": "2026-11-10", "src": "SMI (ITIC)", "title": "ITIC 사례: 중개인이 체선료 청구 증빙을 늦게 전달 — 4만8,000달러 청구가 흔들려 중개인이 절반 2만4,000달러 부담", "eTitle": "ITIC Case: a Shipbroker's Delay in Passing On Demurrage Documents Leaves the Broker Paying USD 24,000, Half of a USD 48,000 Claim", "kSum": "ITIC 클레임 리뷰에 따르면, 선주가 양하 지연으로 용선주에게 약 4만8,000달러의 체선료를 청구한 건에서 선박중개인이 증빙 서류를 제때 전달하지 않았다. 이 지연 때문에 용선주의 이의 제기가 선주에게 늦게 전달돼 청구의 약점을 보완할 시간이 없었다. 책임과 인과관계가 불분명해 ITIC가 상업적 합의를 중재했고 중개인이 청구액의 절반인 2만4,000달러를 부담했다. ITIC는 체선료 청구에는 엄격한 계약상 제척기간이 붙는 경우가 많으므로 청구서와 증빙을 받는 즉시 전달하고 전달 시각을 기록으로 남기라고 권고했다.", "eSum": "ITIC's Claims Review describes an owner's demurrage claim of about USD 48,000 for discharge delays in which the shipbroker failed to forward the supporting documents promptly, so the charterers' objections reached the owners too late to fix weaknesses in the claim. With liability and causation unclear, ITIC helped negotiate a commercial settlement and the broker contributed USD 24,000, half the claim. ITIC notes that demurrage claims often carry tight contractual time bars: pass on claims and documents as soon as they arrive and keep a record of when.", "kImp": "관리사·운항 담당도 같은 위험에 노출된다. 체선료·오프하이어·화물 클레임 서류(SOF, NOR, 타임시트)는 수령 즉시 전달하고 발송 기록을 남기는 절차를 둘 것.", "eImp": "Managers and operators face the same exposure - forward demurrage, off-hire and cargo claim papers (SOF, NOR, time sheets) on receipt and keep a dispatch record.", "url": "https://www.shipmanagementinternational.com/news/kly5d59ry46dkcg-e2l2l-9nrta-r8bw4-flw4k-hhxde-drbmx-lj7h2-le8dw-c2twb-p79aw-lf3mp-x7lrj-9xgz4-ypwjc-mxead-3sa9y-jyph8-7b93c-jf9r2-36ljk"}]}, {"code": "PNI", "items": [{"code": "PNI", "date": "2026-11-10", "src": "SMI (Britannia P&I)", "title": "Britannia P&I, 12월 2일 무료 웨비나 '컨테이너 화재: 계속되는 업계의 위협' — 머스크·앵글로이스턴·Waves Group 연사", "eTitle": "Britannia P&I to Hold a Free Webinar on 2 December, 'Container Fires: A Continued Industry Menace', With Speakers From Maersk, Anglo-Eastern and Waves Group", "kSum": "Britannia P&I가 12월 2일 09:00(GMT) 누구나 참여할 수 있는 무료 웨비나를 연다. Britannia 손해방지 부문 Charles Chong, 머스크 항해 책임자 Mikkel Hinsch Jensen 선장, 앵글로이스턴 소속으로 컨테이너선 안전포럼(CSSF) 부의장인 Swapnodeep Mondal 선장, Waves Group의 해상 화재·위험물 컨설턴트 Paul Coates가 연사로 나선다. 컨테이너 화재의 흔한 원인, 예방을 위한 실무 조치, 화재 발생 후 진화의 어려움, 과거 사고에서 선원과 육상팀이 얻을 교훈, 업계 대응의 진전을 다룬다.", "eSum": "Britannia P&I will host a free, open webinar at 09:00 GMT on 2 December with Charles Chong of its loss prevention team, Capt. Mikkel Hinsch Jensen (Head of Nautical, Maersk), Capt. Swapnodeep Mondal of Anglo-Eastern, second chairman of the Container Ship Safety Forum, and Paul Coates, marine fire and hazmat consultant at Waves Group. It covers common causes of container fires, practical prevention, the difficulty of firefighting once a fire starts, lessons for crews and shore teams, and industry progress.", "kImp": "컨테이너·전기차 화물 화재 대응은 자동차선에도 직접 관련된다. 선박 안전 담당자와 감독이 참석해 선내 화재 대응 훈련 시나리오에 반영할 만하다.", "eImp": "Container and EV cargo fire response is directly relevant to car carriers too - worth attending by safety staff and superintendents and feeding into onboard fire drill scenarios.", "url": "https://www.shipmanagementinternational.com/news/kly5d59ry46dkcg-e2l2l-9nrta-r8bw4-flw4k-hhxde-drbmx-lj7h2-le8dw-c2twb-p79aw-lf3mp-x7lrj-9xgz4-ypwjc-mxead-3sa9y-jyph8-7b93c-jf9r2-36ljk-cz8h5-dfr73-2bb77-j9md4"}]}, {"code": "CLASS", "items": [{"code": "CLASS", "date": "2026-11-12", "src": "Hellenic Shipping News", "title": "로이드선급, 디지털 성숙도 지수에 'AI 성숙도 평가' 추가 — 참여 기관 100곳 넘어", "eTitle": "Lloyd's Register Adds an AI Maturity Assessment to Its Digital Maturity Index, Now Past 100 Participating Organisations", "kSum": "로이드선급(LR)이 Smart Maritime Network Singapore 2026에서 디지털 성숙도 지수(DMI)에 AI 성숙도 평가를 추가했다고 발표했다. AI 준비도 벤치마킹과 부문별 디지털 활용 사례가 평가에 더해졌으며, 프로그램 참여 기관은 100곳을 넘었다.", "eSum": "Lloyd's Register unveiled at Smart Maritime Network Singapore 2026 an AI maturity assessment within its Digital Maturity Index, adding AI-readiness benchmarking and sector-specific digital use cases; the programme has passed 100 participating organisations.", "kImp": "AI 도구를 업무에 쓰는 관리사는 데이터 품질·거버넌스·검증 절차 수준을 외부 기준으로 점검해 볼 수 있다. 선주·용선주 실사에서도 유사 질문이 늘 전망이다.", "eImp": "Managers using AI tools can benchmark data quality, governance and validation against an external standard; expect similar questions in owner and charterer due diligence.", "url": "https://www.hellenicshippingnews.com/shipping-puts-ai-readiness-to-the-test-with-new-maturity-benchmark/"}, {"code": "CLASS", "date": "2026-11-11", "src": "코리아쉬핑가제트", "title": "한국선급, 제32회 ISO 정기 세미나서 ISO 경영시스템 우수 6개사에 감사패 — 선박관리사 포함", "eTitle": "Korean Register Honours Six Companies for Exemplary ISO Management Systems at Its 32nd ISO Seminar, Including Ship Managers", "kSum": "한국선급(KR)이 11월 4일 부산 아스티호텔에서 열린 제32회 ISO 정기 세미나에서 ISO 경영시스템을 모범적으로 운영한 6개 기업(삼우티이에스, 상지해운, 성림제관, 코리아쉽매니져스, 씨넷, 포천마린)에 감사패를 전달했다.", "eSum": "At its 32nd ISO seminar in Busan on 4 November, Korean Register presented plaques of appreciation to six companies for exemplary operation of ISO management systems: Samwoo TES, Sangji Shipping, Sunglim, Korea Ship Managers, Seanet and Pocheon Marine.", "kImp": "ISO 9001·14001·45001 통합 운영 성과는 선주 실사와 입찰에서 차별화 근거가 된다.", "eImp": "A track record of integrated ISO 9001, 14001 and 45001 operation is a differentiator in owner due diligence and tenders.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=148476"}]}, {"code": "COMM", "items": [{"code": "COMM", "date": "2026-11-12", "src": "Hellenic Shipping News", "title": "10월 중고선 168척 거래 — 탱커 82척(+61%)으로 절반, 벌크 57척(−30.5%), 공개 투자액 약 47억 달러", "eTitle": "October S&P: 168 Vessels Change Hands - Tankers 82 (+61%) Make Up Half, Dry Bulk 57 (-30.5%), Disclosed Investment About USD 4.7bn", "kSum": "10월 중고선 거래는 168척으로 전년과 같고 9월보다 2% 많았다. 탱커 거래가 61% 늘어난 82척으로 전체의 49%를 차지했고, 건화물선은 30.5% 줄어든 57척이었다. 공개된 투자액은 약 47억 달러로 탱커 29억 달러, 벌크 11억 달러였다.", "eSum": "A total of 168 vessels changed hands in October, unchanged year on year and 2% above September. Tanker sales rose 61% to 82 ships, 49% of transactions, while dry bulk fell 30.5% to 57. Disclosed investment was about USD 4.7bn, with USD 2.9bn in tankers against USD 1.1bn in dry bulk.", "kImp": "탱커 매매가 활발하면 관리 이전(인수·인도) 수요도 늘어난다. 인수 선박의 상태 평가와 선급·기국 이전 일정 관리 역량이 수주 경쟁력이다.", "eImp": "Active tanker S&P means more management takeovers; condition assessment and class and flag transfer scheduling are the capabilities that win them.", "url": "https://www.hellenicshippingnews.com/tankers-in-high-demand-during-october/"}, {"code": "COMM", "date": "2026-11-12", "src": "Hellenic Shipping News · 코리아쉬핑가제트", "title": "BDI 6일 연속 상승해 2,959 — 케이프 4,700(+5.5%), 파나막스 2,103; 11/10 KDCI 27,720", "eTitle": "Baltic Dry Index Rises for a Sixth Session to 2,959 - Capesize 4,700 (+5.5%), Panamax 2,103; KDCI at 27,720 on 10 November", "kSum": "발틱 건화물선 운임지수(BDI)가 3.4% 오른 2,959포인트로 6거래일 연속 상승해 10월 8일 이후 최고치를 기록했다. 케이프사이즈 지수는 5.5% 오른 4,700, 파나막스 지수는 1.4% 오른 2,103으로 10월 23일 이후 최고였다. 11월 10일 BDI는 2,862, 한국해양진흥공사의 한국형 건화물선 운임지수(KDCI)는 27,720이었고 케이프 시장은 대서양 수역이 호조였다.", "eSum": "The Baltic Dry Index rose 3.4% to 2,959 points, a sixth straight gain and the highest since 8 October. The capesize index gained 5.5% to 4,700 and the panamax index 1.4% to 2,103, its highest since 23 October. On 10 November the BDI stood at 2,862 and the Korea Ocean Business Corporation's KDCI at 27,720, with the Atlantic leading the capesize market.", "kImp": "운임 강세기에는 off-hire 하루의 기회비용이 커진다. 벌크선은 화물창 준비 불합격·기관 고장으로 인한 지연을 줄이는 데 집중할 것.", "eImp": "In a strong market each off-hire day costs more - bulkers should focus on avoiding hold-inspection failures and machinery delays.", "url": "https://www.hellenicshippingnews.com/baltic-dry-index-up-for-6th-day/"}, {"code": "COMM", "date": "2026-11-12", "src": "Hellenic Shipping News", "title": "10월 미국 컨테이너 수입 267만4,808TEU로 월간 사상 최대 — 전년比 +16%, 중국발 4개월 연속 증가", "eTitle": "US Container Imports Hit a Monthly Record of 2,674,808 TEU in October - Up 16% Year on Year, With China-Origin Volumes Rising for a Fourth Month", "kSum": "10월 미국 컨테이너 수입은 267만4,808TEU로 9월보다 5.0%, 전년 10월보다 16.0% 늘어 2022년 5월의 종전 최고치를 2.0% 웃돌았다. 중국발 수입은 4개월 연속 증가한 98만7,805TEU였다.", "eSum": "US containerised imports totalled 2,674,808 TEU in October, up 5.0% from September and 16.0% year on year, beating the May 2022 record by 2.0%. China-origin imports rose for a fourth consecutive month to 987,805 TEU.", "kImp": "", "eImp": "", "url": "https://www.hellenicshippingnews.com/global-shipping-report-october-u-s-container-imports-hit-record-volume/"}, {"code": "COMM", "date": "2026-11-12", "src": "Hellenic Shipping News", "title": "미 중간선거 후 브렌트 16.6% 급락 — 1월물 94.62달러, '전쟁 프리미엄' 축소", "eTitle": "Brent Falls 16.6% After the US Midterms as the War Premium Is Stripped Out - January Contract Settles at USD 94.62", "kSum": "브렌트유가 10월 30일 고점에서 11월 4일까지 16.6% 떨어졌다. 민주당이 상·하원을 모두 차지한 뒤 1월물은 11월 4일 하루 8.98달러 내린 배럴당 94.62달러에 마감했고, 추세추종 CTA는 10월 30일 이후 원유·제품 약 1억2,600만 배럴을 매도했다.", "eSum": "Brent fell 16.6% between its 30 October peak and 4 November after the Democrats took both chambers of Congress; the January contract settled at USD 94.62/bbl on 4 November after an USD 8.98 drop, and trend-following CTAs sold about 126m bbl of crude and products from 30 October.", "kImp": "유가 급락은 벙커가격과 감속 운항 유인을 바꾼다. 용선계약의 속력·연료소모 보증과 벙커 헤지 조건을 다시 볼 시점이다.", "eImp": "A sharp oil move changes bunker costs and slow-steaming incentives - a point to revisit speed and consumption warranties and bunker hedges.", "url": "https://www.hellenicshippingnews.com/midterms-strip-out-the-war-premium-but-the-next-two-months-make-shorts-a-risky-bet/"}, {"code": "COMM", "date": "2026-11-12", "src": "Hellenic Shipping News", "title": "Flex LNG 3분기 순이익 4,280만 달러 — 평균 TCE 일 78,875달러", "eTitle": "Flex LNG Reports Q3 Net Income of USD 42.8m With an Average TCE of USD 78,875 per Day", "kSum": "Flex LNG의 2026년 3분기 선박 운영 매출은 9,740만 달러(2분기 1억680만 달러), 순이익은 4,280만 달러(주당 0.79달러)였다. 3분기 평균 정기용선 환산 운임(TCE)은 일 78,875달러였다.", "eSum": "Flex LNG reported Q3 2026 vessel operating revenues of USD 97.4m (USD 106.8m in Q2) and net income of USD 42.8m, or USD 0.79 per share, with an average time charter equivalent rate of USD 78,875 per day.", "kImp": "", "eImp": "", "url": "https://www.hellenicshippingnews.com/flex-lng-reports-strongest-third-quarter-results-on-record/"}, {"code": "COMM", "date": "2026-11-12", "src": "쉬핑뉴스넷", "title": "하나증권 '2027년 컨테이너선 공급 +9~20% vs 수요 +4%' — 정기선 보수적 접근 권고, SCFI 1,400이 손익분기; 9월 세계 물동량 1,735만TEU(+8%)", "eTitle": "Hana Securities: Container Ship Supply to Grow 9-20% in 2027 Against Demand of About 4% - Cautious View on Liners, SCFI 1,400 Seen as Break-Even; Global Volumes 17.35m TEU in September (+8%)", "kSum": "하나증권 안도현 애널리스트는 2027년 컨테이너선 공급 증가율을 약 9%, 수에즈운하 복귀에 따른 유효 선복 증가까지 감안하면 9~20%로 전망했다. 수요 증가율은 약 4%로, 2026년에 있었던 전쟁 이후 재고 축적과 관세 대비 조기 선적 수요가 약해진다는 판단이다. 공급 증가가 수요를 5%p 이상 웃돌아 운임 하락 압력이 크다며 정기선 업황에 보수적 접근을 권고했다. 하방 지지 요인으로는 선가 상승과 항만 체선(평균 대기 2016년 6.3시간 → 2026년 10.3시간)을 들었고, 글로벌 선사의 영업이익 손익분기는 SCFI 1,400포인트로 추정했다. 한편 9월 세계 컨테이너 물동량은 1,735만TEU로 전년 동월보다 8% 늘었으나 전월보다 1% 줄었다.", "eSum": "Hana Securities analyst Ahn Do-hyun forecasts container ship supply growth of about 9% in 2027, or 9-20% once the effective capacity released by a return to Suez is included, against demand growth of about 4% as the post-war restocking and tariff front-loading seen in 2026 fade. With supply outpacing demand by more than 5 points, he sees heavy pressure on rates and advises a cautious view of liners. Support comes from higher ship prices and port congestion (average waiting time up from 6.3 hours in 2016 to 10.3 hours in 2026); SCFI 1,400 is estimated as the operating break-even for global carriers. Global container volumes were 17.35m TEU in September, up 8% year on year but 1% below August.", "kImp": "수에즈 복귀와 신조 인도가 겹치면 유효 선복이 크게 늘어 용선료 하락 압력이 커진다.", "eImp": "Suez returns plus newbuilding deliveries would sharply raise effective capacity and pressure charter rates.", "url": "https://www.shippingnewsnet.com/news/articleView.html?idxno=72971"}, {"code": "COMM", "date": "2026-11-12", "src": "쉬핑뉴스넷", "title": "매트슨 3분기 순이익 55% 증가 — 중국 항로 호조로 연간 전망 상향; 나비오스는 3.3배", "eTitle": "Matson's Q3 Net Profit Rises 55% and It Lifts Full-Year Guidance on Strong China Service; Navios Earnings Up 3.3 Times", "kSum": "미국 선사 매트슨의 3분기 순이익이 중국 항로 호조에 힘입어 55% 늘었고 연간 실적 전망도 상향됐다. 나비오스는 톤마일 증가에 따른 시황 상승으로 7~9월 순이익이 3.3배로 늘었다.", "eSum": "Matson's third-quarter net profit rose 55% on a strong China service and it raised its full-year outlook; Navios reported July-September net profit up 3.3 times as higher tonne-mile demand lifted the market.", "kImp": "", "eImp": "", "url": "https://www.shippingnewsnet.com/news/articleView.html?idxno=72976"}, {"code": "COMM", "date": "2026-11-11", "src": "Splash247", "title": "석탄 해상물동량 재편 — 인도네시아 수출 후퇴, 남부 아프리카 선적 사상 최대", "eTitle": "Coal's New World Order Takes Shape - Indonesian Exports Retreat While Southern African Shipments Set Records", "kSum": "2026년 석탄 교역 흐름이 바뀌며 건화물선 시장에 승자와 패자가 갈리고 있다. 인도네시아 수출은 줄고 남부 아프리카 선적은 기록을 세우고 있으며, Clarksons Research는 해상 석탄 물동량이 소폭 늘 것으로 전망한다.", "eSum": "Coal trade shifts in 2026 are creating winners and losers in dry bulk: Indonesian exports are retreating while southern African shipments set records, and Clarksons Research forecasts a modest rise in seaborne coal trade.", "kImp": "남아공·모잠비크 적재 항차가 늘 수 있다. 해당 항만의 흘수·기상 제약과 화물창 청결 기준을 미리 확인할 것.", "eImp": "Loadings in South Africa and Mozambique may increase - check draft and weather restrictions and hold-cleanliness standards at those ports in advance.", "url": "https://splash247.com/coals-new-world-order-takes-shape/"}, {"code": "COMM", "date": "2026-11-11", "src": "Splash247", "title": "Hartnoll의 Eastway, 수에즈막스 4척 중국 발주로 탱커 시장 복귀 — 약 3억2,000만 달러; Monjasa는 BSM 제품선 5척 인수", "eTitle": "Hartnoll's Eastway Returns to Tankers With Four Suezmax Newbuildings in China Worth About USD 320m; Monjasa Buys Five Product Tankers From Bernhard Schulte", "kSum": "Tim Hartnoll 계열 Eastway가 중국에 수에즈막스 4척을 발주하며 탱커 시장에 복귀했다(Alphaliner 추정 3억2,000만 달러). Monjasa는 Bernhard Schulte로부터 2010~2011년 건조 자매 제품운반선 5척을 사들여 서아프리카 선박연료 사업을 강화했는데, 회사 사상 최대 선대 거래다.", "eSum": "Eastway, linked to Tim Hartnoll's group, returned to the tanker market with four suezmax newbuildings in China, a deal Alphaliner estimates at USD 320m. Monjasa bought five 2010-2011-built sister product tankers from Bernhard Schulte, its largest-ever fleet deal, to strengthen its West African marine fuel operations.", "kImp": "", "eImp": "", "url": "https://splash247.com/hartnolls-eastway-makes-320m-tanker-comeback/"}, {"code": "COMM", "date": "2026-11-10", "src": "gCaptain", "title": "'Nonsense rate' — 이란 전쟁이 드러낸 VLCC 운임지표 TD3C 논란, Mercuria는 발틱거래소 제소", "eTitle": "'Nonsense Rate': the Iran War Exposes Turmoil Behind the TD3C VLCC Benchmark, With Mercuria Suing the Baltic Exchange", "kSum": "발틱거래소가 발표하는 라스타누라–닝보 VLCC 운임지표 TD3C는 2월 28일 미·이스라엘의 이란 공격 이후에도 3~7월 계속 공표됐고, 거래소는 '비상 상황'에서 패널이 파생상품 가격을 참고할 수 있다는 지침을 냈다. 지표 산출 담당 직원은 3월 23일 내부 스프레드시트에 'Nonsense rate'라고 적으며 한동안 자신의 추정치 제출을 중단했다. TD3C는 상반기 약 174억 유로 규모 파생상품 시장의 기준이며, 최대 이용자인 Mercuria가 발틱거래소를 상대로 소송 중이다.", "eSum": "TD3C, the Baltic Exchange's VLCC rate for Ras Tanura-Ningbo, kept being published from March to July after the US and Israel attacked Iran on 28 February, and the Baltic issued guidance letting panellists consider derivatives prices in extraordinary circumstances. The employee responsible for producing it wrote 'Nonsense rate' in internal notes on 23 March and stopped submitting his own estimates for a time. TD3C underpins a derivatives market worth about EUR 17.4bn in the first half; its largest user, Mercuria, is suing the Baltic.", "kImp": "지수 연동 용선료·FFA 정산에 쓰이는 지표의 신뢰성 문제다. 지수 연동 계약은 지표 중단·왜곡 시 대체 산정 조항을 확인할 것.", "eImp": "This is about the reliability of a benchmark used in index-linked hire and FFA settlement - check index-linked contracts for fallback clauses if a benchmark is suspended or distorted.", "url": "https://gcaptain.com/nonsense-rate-iran-war-exposes-turmoil-behind-key-tanker-benchmark/"}]}, {"code": "GEO", "items": [{"code": "GEO", "date": "2026-11-12", "src": "Hellenic Shipping News (Platts)", "title": "미 재무부, 제재 유조선 매입을 건별로 허용할 수도 — '그림자 선대' 축소 방안", "eTitle": "US Treasury May Allow Purchases of Sanctioned Tankers Case by Case to Shrink the Shadow Fleet", "kSum": "미 재무부가 제재 대상 선박을 기업이 매입해 합법 운송으로 되돌리는 것을 건별로 허용할 수 있다고 정부 소식통이 Platts에 밝혔다. 그림자 선대 규모를 줄이되 제재 대상자가 이익을 얻지 않도록 한다는 접근이다.", "eSum": "The US Treasury may let companies buy sanctioned vessels and return them to legitimate trade on a case-by-case basis, a US official told Platts - an approach meant to shrink the shadow fleet while ensuring no sanctioned person benefits.", "kImp": "제재 이력 선박의 매입·관리 인수는 OFAC 허가와 실사 기록이 전제다. 관리 인수 전 선박 이력(AIS 공백, STS, 기국 변경)을 반드시 조사할 것.", "eImp": "Buying or taking management of a ship with sanctions history requires OFAC authorisation and documented due diligence - investigate vessel history (AIS gaps, STS, flag changes) before any takeover.", "url": "https://www.hellenicshippingnews.com/us-treasury-may-allow-purchase-of-sanctioned-tankers-on-case-basis/"}, {"code": "GEO", "date": "2026-11-11", "src": "Splash247", "title": "우크라이나 드론, 러시아 발트해 수출항 우스트루가 공격 — 항만시설 화재, 3명 부상", "eTitle": "Ukrainian Drones Strike Russia's Major Baltic Export Port of Ust-Luga - Port Infrastructure on Fire, Three Injured", "kSum": "우크라이나가 러시아 발트해 주요 수출항 우스트루가를 대규모 드론으로 공격해 항만 시설에 화재가 났고 3명이 다친 것으로 전해졌다.", "eSum": "Ukraine launched a major drone attack on Russia's Ust-Luga port on the Baltic, setting port infrastructure on fire, with three people reported injured.", "kImp": "발트해 러시아 항만 인근 통항·기항 선박은 전쟁위험 보험 구역 지정과 항만 보안 정보를 재확인할 것.", "eImp": "Ships trading near Russian Baltic ports should re-check war-risk area listings and port security information.", "url": "https://splash247.com/ukrainian-drones-strike-major-russian-baltic-export-port/"}, {"code": "GEO", "date": "2026-11-11", "src": "Hellenic Shipping News (Xclusiv)", "title": "미 중간선거 이후의 해운 — 민주당 상·하원 장악, 새 의회는 2027년 1월 출범", "eTitle": "Shipping at a New Crossroads After the US Midterm Election - Democrats Take House and Senate, New Congress Sits in January 2027", "kSum": "선박중개사 Xclusiv는 11월 3일 미 중간선거에서 민주당이 상·하원을 모두 확보했다고 정리했다. 물가, 높은 에너지 가격, 장기화한 이란 분쟁이 표심에 크게 작용했으며 새 의회는 2027년 1월 출범한다. 관세·입항료·제재 정책의 변화 가능성이 해운 시황의 변수로 꼽힌다.", "eSum": "Shipbroker Xclusiv notes that Democrats secured both the House and Senate in the 3 November US midterms, with inflation, high energy prices and the prolonged conflict with Iran weighing on voters; the new Congress takes office in January 2027. Possible shifts in tariffs, port fees and sanctions are the variables for shipping.", "kImp": "", "eImp": "", "url": "https://www.hellenicshippingnews.com/shipping-in-new-crossroads-after-the-us-mid-term-election/"}, {"code": "GEO", "date": "2026-11-10", "src": "gCaptain (Reuters)", "title": "우크라이나 드론 공격 재개로 러시아 정제능력 약 30% 감소 — 일주일 새 주요 정유소 35곳 중 9곳 차질, 2위 키리시 정유소 화재", "eTitle": "Renewed Ukrainian Drone Attacks Cut Russian Refining Capacity by About 30% - Nine of 35 Major Refineries Disrupted in a Week, Fire at Kirishi, the Second-Largest", "kSum": "에너지 시설 공격 중단 합의가 무산된 뒤 10월 말 재개된 우크라이나의 드론 공격으로, 지난 일주일 사이 러시아 주요 정유소 35곳 중 9곳(랴잔·야로슬라블·볼가 지역 등)이 가동 차질이나 비상 상황을 겪었다고 로이터가 업계 소식통 2명을 인용해 전했다. 영향을 받은 설비의 명목 능력은 하루 약 30만 톤(약 220만 배럴)으로 전체 약 93만 톤의 30% 수준이며, 실제 원유 처리 감소는 하루 20만 톤에 이를 수 있다. 러시아 2위 정유소 키리시는 11월 9일 드론 공격으로 불이 나 1명이 숨졌다. 러시아는 국내 연료 부족 속에서도 미국과의 합의에 따라 디젤을 수출하고 있다.", "eSum": "After a ceasefire on energy strikes failed, Ukraine's drone attacks resumed in late October; Reuters, citing two industry sources, says nine of Russia's 35 major refineries (including Ryazan, Yaroslavl and a Volga plant) were disrupted or hit by emergencies in the past week. The affected plants have nameplate capacity of about 300,000 tonnes a day (about 2.2m b/d) out of roughly 930,000 tonnes, or about 30%, and actual crude runs could fall by up to 200,000 tonnes a day. Kirishi, Russia's second-largest refinery, was set on fire by a drone on 9 November, killing one person. Russia is still shipping diesel abroad under an export deal with the US despite domestic shortages.", "kImp": "정제 차질은 러시아산 제품유 수출을 줄이고 원유 수출을 늘려 제품선·원유선 항로를 바꾼다. 러시아 항만 기항 여부와 제재·전쟁위험 조건을 항차마다 확인할 것.", "eImp": "Refinery outages cut Russian product exports and push more crude to export, shifting product and crude tanker flows - check sanctions and war-risk terms voyage by voyage for any Russian port call.", "url": "https://gcaptain.com/recent-ukrainian-attacks-have-reduced-russias-oil-processing-capacity-by-30-sources-say/"}, {"code": "GEO", "date": "2026-11-10", "src": "gCaptain (Bloomberg)", "title": "카타르 LNG 선적 11월 10일 이동평균 13~15항차로 증가(10월 약 11) — 그래도 전쟁 전의 절반, 호르무즈 통과는 10일간 11척으로 정체", "eTitle": "Qatar LNG Loadings Rise to 13-15 Cargoes on a 10-Day Average (About 11 in October) - Still Half the Pre-War Pace, While Hormuz Exits Stay Flat at 11 Laden Ships in 10 Days", "kSum": "블룸버그·Kpler·코페르니쿠스 자료에 따르면 라스라판의 LNG 선적은 11월 들어 10일 이동평균 13~15항차로 10월의 약 11항차보다 늘었지만 여전히 전쟁 전 속도의 절반 수준이다. 반면 11월 8일까지 10일간 호르무즈를 빠져나온 카타르산 LNG 적재선은 11척으로 지난 한 달과 비슷해, 선적 증가만큼 통과가 늘지는 않았다. 라스라판과 해협의 선박 대부분이 위치 신호를 송출하지 않아 두 수치 모두 검증이 어렵다는 단서가 붙는다.", "eSum": "Bloomberg, Kpler and Copernicus data put Ras Laffan loadings at 13-15 LNG cargoes on a 10-day moving average so far in November, up from about 11 in October but still roughly half the pre-war pace. Eleven laden Qatari LNG carriers exited the Strait of Hormuz in the 10 days to 8 November, broadly unchanged over the past month, so transits have not risen in step with loadings. Both figures are hard to verify because most ships at Ras Laffan and in the Strait do not transmit positions.", "kImp": "걸프 LNG 선적 재개는 가스선의 호르무즈 통항 증가를 뜻한다. 해당 선박은 통항 위험평가와 선원 동의 절차를 갱신할 것.", "eImp": "Resumed Gulf LNG loadings mean more gas carrier transits of Hormuz - update transit risk assessments and crew consent for those ships.", "url": "https://gcaptain.com/qatar-lng-loadings-pick-up-to-around-half-of-pre-war-levels/"}, {"code": "GEO", "date": "2026-11-10", "src": "gCaptain (Reuters)", "title": "[후속] 러시아산 디젤 4만 톤 실은 Agioi Fanendes, 미 동부 연안서 2노트로 대기 — 양하항 미지정, 뉴저지 주지사 '수령 시 연방법 위반' 경고", "eTitle": "[Follow-up] Agioi Fanendes With 40,000 Tonnes of Russian Diesel Waits Off the US East Coast at 2 Knots - No Discharge Port Nominated; New Jersey's Governor Warns Receivers They Would Break Federal Law", "kSum": "몰타기 제품선 Agioi Fanendes(그리스 Eastmed 관리)가 10월 22일 러시아 프리모르스크에서 초저유황 디젤 4만 톤을 싣고 뉴욕을 목적지로 향하다 미 동부 연안에서 멈춰 있다. 관리사는 '여전히 지시 대기 중'이라고 밝혔고, Vortexa는 속력이 약 10노트에서 2노트로 떨어진 점으로 미뤄 구매자가 정해지지 않은 것으로 봤다. 뉴저지 주지사는 항만 당국과 터미널 운영사에 러시아산 디젤 수령은 연방법 위반으로 민·형사 처벌 대상이 될 수 있다고 경고했고, 양당 상원의원들도 수입 금지법을 지적했다. 미 에너지장관은 '다른 항구로 갈 것'이라며 세계 시장에 디젤을 공급하는 것이 목표라고 말했다.", "eSum": "The Malta-flagged product tanker Agioi Fanendes, managed by Greece-based Eastmed, loaded 40,000 tonnes of ultra-low sulphur diesel at Primorsk on 22 October for New York and has halted off the US East Coast. The manager says it is still awaiting orders; Vortexa notes its speed fell from about 10 knots to about 2, suggesting no buyer is fixed. New Jersey's governor warned port officials and terminal operators that accepting Russian diesel would break federal law and risk civil and criminal penalties, and senators from both parties pointed to the import ban. The US energy secretary said the cargo will go to another port and that the aim is to get the diesel into world markets.", "kImp": "정부 승인을 받은 화물이라도 주(州)·터미널 단계에서 수령이 막히면 선박은 체선과 법적 위험을 떠안는다. 제재 연관 화물은 양하항 확정과 용선계약의 제재 조항을 선적 전에 확인할 것.", "eImp": "Even a government-approved cargo can be blocked at state or terminal level, leaving the ship with delay and legal exposure - confirm the discharge port and the charter party sanctions clause before loading any sanctions-linked cargo.", "url": "https://gcaptain.com/russian-diesel-tanker-awaits-orders-off-u-s-coast-amid-import-ban-dispute/"}]}, {"code": "HOT", "items": [{"code": "HOT", "date": "2026-11-11", "src": "The Maritime Executive", "title": "인터뷰: Arsenio Dominguez IMO 사무총장 — '책임 추궁보다 해법, 더 안전하고 투명한 해운'", "eTitle": "Executive Interview: IMO Secretary-General Arsenio Dominguez - Solutions Over Blame, a Safer and More Transparent Industry", "kSum": "IMO 사무총장 Arsenio Dominguez는 인터뷰에서 업계의 난제를 영구적 장벽이 아니라 고치거나 피해 갈 일시적 장애물로 본다고 말했다. 책임을 따지기보다 해법을 찾는 데 우선순위를 두며, 해운을 더 안전하고 투명하게 만드는 데 초점을 맞추겠다고 밝혔다. MEPC 85(11월 30일~12월 3일)와 넷제로 프레임워크 재논의를 앞둔 시점이다.", "eSum": "In an interview, IMO Secretary-General Arsenio Dominguez says he treats the industry's challenges as temporary obstacles to be fixed or avoided rather than permanent barriers, prioritising solutions over blame with a focus on making shipping safer and more transparent - ahead of MEPC 85 on 30 November-3 December and renewed talks on the Net-Zero Framework.", "kImp": "", "eImp": "", "url": "https://maritime-executive.com/magazine/executive-interview-arsenio-dominguez-secretary-general-imo"}]}, {"code": "SYS", "items": [{"code": "SYS", "date": "2026-11-11", "src": "SMI (Marlink)", "title": "Marlink 선내 엣지 플랫폼 XChange NextGen, BV로부터 IACS UR E27 사이버 복원력 인증", "eTitle": "Marlink's XChange NextGen Onboard Edge Platform Gains IACS UR E27 Cyber Resilience Certification From Bureau Veritas", "kSum": "Marlink의 차세대 선내 엣지 플랫폼 XChange NextGen이 승인 범위 내에서 IACS UR E27 Rev.1과 Bureau Veritas NR659 요건을 충족한다는 인증을 받았다. 인증은 사이버보안 기능뿐 아니라 보안 개발·유지보수·업데이트 절차까지 포함한다. UR E27은 개별 선내 시스템·장비에, UR E26은 선박 전체의 사이버 복원력에 적용된다. 이 플랫폼은 연결성, 네트워크 오케스트레이션, 사이버보안, 클라우드 서비스를 묶고 데이터를 선내에서 처리해 분석·AI 활용을 지원하며 하드웨어 구성을 단순화한다.", "eSum": "Marlink's next-generation onboard edge platform XChange NextGen has been certified as meeting IACS UR E27 Rev.1 and Bureau Veritas NR659 within the approved scope, covering both cyber security capabilities and the processes for secure development, maintenance and updates. UR E27 applies to individual onboard systems and equipment, UR E26 to cyber resilience at ship level. The platform combines connectivity, network orchestration, cyber security and cloud services, processes data on board for analytics and AI, and reduces hardware complexity.", "kImp": "신조선(2024년 7월 이후 계약)에 UR E26/E27이 적용되면서 통신·IT 장비도 형식 인증 증빙이 필요해졌다. 장비 교체·추가 시 E27 인증 여부를 구매 사양에 넣을 것.", "eImp": "With UR E26/E27 applying to newbuildings contracted from July 2024, communications and IT equipment also needs certification evidence - put E27 certification into purchase specifications when replacing or adding equipment.", "url": "https://www.shipmanagementinternational.com/news/kly5d59ry46dkcg-e2l2l-9nrta-r8bw4-flw4k-hhxde-drbmx-lj7h2-le8dw-c2twb-p79aw-lf3mp-x7lrj-9xgz4-ypwjc-mxead-3sa9y-jyph8-7b93c-jf9r2-36ljk-cz8h5-dfr73-2bb77-j9md4-7fcpt-8ljtk"}]}, {"code": "SMGR", "items": [{"code": "SMGR", "date": "2026-11-11", "src": "Splash247", "title": "MSM CEO '선박관리의 다음 경쟁력은 규모가 아니라 신뢰' — 통합이 선주·선박·선원과의 거리를 넓혀선 안 돼", "eTitle": "MSM: Shipmanagement's Next Advantage Will Be Trust, Not Size", "kSum": "최근 Maryam Shipmanagement에서 사명을 바꾼 MSM의 Faouzi Fradi CEO는 선박관리 업계의 통합이 관리사를 선주·선박·선원으로부터 멀어지게 만들 필요는 없다고 주장했다. 규모 경쟁보다 가까운 소통과 신뢰가 다음 차별화 요소라는 메시지다.", "eSum": "MSM chief executive Faouzi Fradi, whose company recently rebranded from Maryam Shipmanagement, argues that consolidation in ship management need not make firms more distant from owners, vessels or seafarers - closeness and trust, not scale, are the next differentiator.", "kImp": "중형 관리사에는 기회다. 선주 보고의 투명성(비용·성능·사고), 현장 대응 속도, 선원과의 직접 소통을 서비스 수준으로 명문화해 보일 것.", "eImp": "An opening for mid-sized managers: put transparent owner reporting (cost, performance, incidents), response speed and direct crew contact into visible service levels.", "url": "https://splash247.com/msm-shipmanagements-next-advantage-will-be-trust-not-size/"}, {"code": "SMGR", "date": "2026-11-11", "src": "SMI (Wallem)", "title": "Wallem, 그리스 선박관리 총괄에 Apostolos Poulovassilis 선임 — 아테네 사무소 신설·그리스 선주 영업 확대", "eTitle": "Wallem Group Appoints Apostolos Poulovassilis as General Manager, Ship Management, Greece, to Set Up a Greek Office and Grow Business With Greek Owners", "kSum": "Wallem Group이 11월부로 Apostolos Poulovassilis를 신설 직책인 그리스 선박관리 총괄(General Manager, Ship Management, Greece)에 선임했다. 그는 해사 분야 경력 35년 이상으로 기관사로 출발해 로이드선급에서 25년간 검사원부터 그리스·유럽 사업 총괄까지 지냈고, Eletson Corporation과 Aegean Shipping Management의 COO·CEO, 최근에는 Ocean Technologies Group/OneOcean 고위직을 맡았다. 그리스 사무소를 세워 선박관리 입지를 넓히고 그리스 선주와의 관계 강화, 신규 수주, 서비스 확대를 맡는다.", "eSum": "Wallem Group has appointed Apostolos Poulovassilis to the newly created role of General Manager, Ship Management, Greece, from November, reporting to the Managing Director, Ship Management. He has more than 35 years in maritime: a former marine engineer, 25 years at Lloyd's Register rising to lead its Greek and European business, then COO and CEO roles at Eletson Corporation and Aegean Shipping Management, and most recently a senior role at Ocean Technologies Group/OneOcean. He will establish and develop a Greek office, win new business and strengthen ties with Greek owners.", "kImp": "대형 제3자 관리사들이 그리스 선주 시장 공략을 위해 현지 거점과 선급·선주사 출신 인사를 영입하고 있다. 선주 접점에 기술·선급 경력자를 두는 것이 신뢰 확보 방식으로 자리 잡는 흐름이다.", "eImp": "Third-party managers are opening local bases and hiring class and owner-side veterans to win Greek owners - putting technical and class experience at the owner interface is becoming the way to build trust.", "url": "https://www.shipmanagementinternational.com/news/kly5d59ry46dkcg-e2l2l-9nrta-r8bw4-flw4k-hhxde-drbmx-lj7h2-le8dw-c2twb-p79aw-lf3mp-x7lrj-9xgz4-ypwjc-mxead-3sa9y-jyph8-7b93c-jf9r2-36ljk-cz8h5-dfr73-2bb77-j9md4-7fcpt-8ljtk-24lmz-jnm7a-lndkh"}]}]};